sessions.push(...[{"number":37,"id":"tTcxVv8HHNw","url":"https://www.youtube.com/watch?v=tTcxVv8HHNw","type":"session","type_he":"סשן","duration":"31:59 דקות","title_he":"מעבר לזיכרון: עיבוד לקחים ברקע","speaker_he":"לאמיס מוקטה · אנתרופיק","summary":"הרצאה על התפתחות ה-context engineering בשנה האחרונה: מקבצי CLAUDE.md, דרך כלי זיכרון ו-skills, אל זיכרון כמערכת קבצים, ועד מה שנדרש כדי להפעיל זאת בייצור. החידוש הוא תהליך \"עיבוד לקחים ברקע\" (בהרצאה dreaming): תהליך אצווה שרץ מחוץ לסשנים, קורא תמלילים של הרבה סוכנים ומציע שינויים בזיכרון.","takeaways":["לבנות זיכרון פשוט קודם.","גרסאות, חתימת תוכן והרשאות נדרשים בייצור.","עיבוד לקחים ברקע רואה דפוסים בין סשנים.","מפרידים בין הצעה לשינוי בזיכרון לבין החלטה מה לאשר."],"category":"הקשר וזיכרון","coverage":"תמלול מלא כולל שאלות ותשובות.","source_basis":"תמלול מלא של ההרצאה (כ-5,200 מילים) כולל שלוש שאלות מהקהל, בהשוואה לטקסט הרשמי. לא נצפה בסרטון.","lead":"הרצאה על התפתחות ה-context engineering בשנה האחרונה: מקבצי CLAUDE.md, דרך כלי זיכרון ו-skills, אל זיכרון כמערכת קבצים, ועד מה שנדרש כדי להפעיל זאת בייצור. החידוש הוא תהליך \"עיבוד לקחים ברקע\" (בהרצאה dreaming): תהליך אצווה שרץ מחוץ לסשנים, קורא תמלילים של הרבה סוכנים ומציע שינויים בזיכרון.","chapters":[{"title":"הצגה ותוכנית ההרצאה","body":["המנחה מציג את הנושא כ\"קרוב ללבי: שינה\" וקורא לבמה מישהי מ-Anthropic. לאמיס אומרת שהיא חברת צוות טכני בצוות Applied AI, שיושב בין מחקר, מוצר ו-go to market. הצוות עובד גם על פרויקטים פנימיים וגם ישירות עם לקוחות שבונים סוכנים בחזית. היא עובדת מול סטארטאפים ומייסדים, ו\"יש לי את המקום הכי טוב בבית\" כי הם דוחפים אותה לגבול של מה שאפשרי.","השאלה שחוזרת: מה נדרש כדי לתרגם אינטליגנציית מודל גולמית למוצרים עמידים וניתנים להרחבה. אחד המנופים: context engineering, ועליו ההרצאה. התוכנית: סיכום מה קרה ב-context engineering בשנה האחרונה, מצב האמנות של ניהול זיכרון, מה צריך כדי לבנות מערכות כאלה בייצור, ולבסוף לאן זה הולך בדרך ל-continual learning ובמיוחד לפרדיגמה שנקראת dreaming."],"points":[],"kind":"idea"},{"title":"למה הקשר ולא רק מודל חכם יותר","body":["היא אומרת שמודלים חדשים משתחררים כל הזמן ונעשים חכמים יותר, אבל כשפורסים אותם אצלכם, האינטליגנציה לבדה לא תצטבר, כי המודל צריך הקשר שיעזור לו לבצע את המשימות הספציפיות. הרבה מההקשר הזה \"אורתוגונלי\" לאינטליגנציה של המודל: המודל החדש ביותר לא ידע מהקופסה מה נדרש כדי להצליח בארגון שלכם.","לכן השקעה ב-context engineering היא השקעה טובה, כי \"היא מכפילה את האינטליגנציה גם כשהמודלים נעשים חכמים יותר\". הבעיות המוכרות: סוכן שלא מכיר את ה-codebase, או את העדפות המשתמש, וסוכן שלא משתפר בפעם הבאה שהוא מבצע משימה, כלומר אין אפקט של למידה מתמשכת."],"points":[],"kind":"idea"},{"title":"השלב הראשון: קבצי CLAUDE.md","body":["במדיניות Anthropic: \"do the simple thing that works\". ציר זמן של השנה האחרונה מתחיל בקבצי CLAUDE.md שהושקו עם Claude Code. היא אומרת שהם היו \"יעילים באופן לא סביר\": קובץ markdown עם כמה הוראות על ה-codebase, הארגון והעדפות המשתמש, שמוזרק לתחילת ההקשר בתחילת סשן, הוביל את המודל טוב מאוד.","אבל למדו גם מה לא עובד: כשהקובץ הופך ארוך, איך מנהלים אותו לאורך זמן? ועם זאת, ההבנה שקובץ markdown פשוט שאפשר לקרוא אותו ושהסוכן והאדם כותבים אליו עובד היטב."],"points":[],"kind":"idea"},{"title":"השלב השני: כלי זיכרון (in-band)","body":["הכיוון השני: כלי זיכרון שבהם הסוכן מנהל את מערכת הזיכרון שלו באופן אוטונומי: הוא מחליט מתי לקרוא, לכתוב ולעדכן. כל זה קורה \"in-band\", בתוך הקשר של סשן. הסוכן חושב במהלך הסשן מה כדאי למשוך מהזיכרון ומה לכתוב אליו. אוטונומיה עובדת טוב. עם הזמן פיתחו מערכות שבהן פחות דעתניים לגבי איך הכלים נראים."],"points":[],"kind":"idea"},{"title":"השלב השלישי: skills והגילוי ההדרגתי","body":["Skills פותרים את בעיית ההקשר שגדל. הרעיון החכם הוא \"progressive disclosure\": הסוכן קורא רק את ה-front matter (כמה משפטים בראש הקובץ) לפני טעינת ה-skill, ובגוף הקובץ אפשר לשים כמה פירוט שרוצים. כך מקבלים עומק בלי להעמיס על חלון ההקשר.","היא נותנת אנלוגיה: מדף ספרים בחדר. כשמישהו מדבר איתי, אני סורקת את כותרות הספרים ובוחרת אחד כשצריך. אם מישהו פונה אליי בצרפתית ויש לי מילון צרפתי, אני שולפת אותו ומקבלת הקשר בלי ש\"שבע שנות שיעורי צרפתית\" יהיו טעונות בראש מראש.","ה-skills טובים בתהליכים עם זרימה פרוצדורלית שיש לכם עמדה לגביה. אבל נשאר צוואר בקבוק: הם עדיין מונעים על ידי בני אדם וסוכנים יחד, גם אם הסוכן עוזר לכתוב אותם, ואתם עדיין דעתניים לגבי מה צריך skill."],"points":[],"kind":"idea"},{"title":"מצב האמנות: זיכרון כמערכת קבצים","body":["מה שנחשב כיום לפרקטיקה הטובה ביותר: למדל מערכות זיכרון כמערכת קבצים. אפשר למלא אותה ב-markdown. סוכנים טובים בשימוש בכלי מערכת קבצים רגילים כמו bash ו-grep, אז נותנים להם לחפש בה במקום לכפות כלי קריאה וכתיבה ייעודיים. החיפוש משקף את אותו עיקרון של progressive disclosure, ואפשר לאנדקס היטב.","הלקחים: markdown מצוין לקריאת זיכרונות, אפשר לתת לזיכרונות לגדול אבל לתת לסוכנים כלי אינדוקס וחיפוש מהיר, ולתת לסוכנים אוטונומיה בכתיבה. אם בונים כך, מקבלים תחושה של למידה מתמשכת כי הסוכנים משתפרים במשימות שלהם."],"points":[],"kind":"idea"},{"title":"מה נשבר בייצור","body":["כשמנסים להרחיב לייצור, עם הרבה סוכנים שמשתפים פעולה, שרצים לאורך זמן ועם codebases מורכבים, צצות בעיות שהם רואים שוב ושוב: כמה סוכנים שכותבים לאותו קובץ זיכרון בו־זמנית. סוכן אחד שנתקל בבעיה וכותב להקשר ברמת הארגון שכל הסוכנים האחרים קוראים, ואם משהו שם שגוי זה \"יתפשט לכולם ויהיה אסון\". בני אדם וסוכנים שמשתפים פעולה על זיכרון, ואיך עוקבים אחרי מה קורה. וזיכרונות שנעשים מיושנים, נכתבו בטעות, או הוזרקו בכוונה זדונית על ידי מי שמנסה להזריק פרומפט לסוכנים."],"points":[],"kind":"idea"},{"title":"ארבעה עקרונות לייצור: גרסאות, מקביליות, הרשאות, ניידות","body":["גרסאות: לשמור גרסאות כדי לדעת מה קרה ולאפשר rollback. לשמור על איזה הקשר העדכון התבסס: איזה סשן, איזה תמליל, ומי עשה אותו (איזה סוכן או אדם).","מקביליות: כשפורסים אלפי סוכנים על אותה מערכת זיכרון, הפתרון הוא hash. סוכן שרוצה לעדכן זיכרון לוקח hash, מנסח את העריכה, ולפני הכתיבה לוקח hash נוסף. אם השניים שונים, הוא לא יכול לכתוב כי מישהו עדכן בינתיים. הוא קורא מחדש את הזיכרון, מנסח עדכון חדש ומנסה שוב.","הרשאות: בבסיסי זיכרון גדולים יש ידע ארגוני מקורו בעמל, ועד \"פנקס טיוטה\" אישי של סוכן. צריך הרשאות: סוכן לא אמור לעדכן לבד את ההקשר הארגוני (read-only), אבל לפנקס שלו יש לו גישת כתיבה.","ניידות: אם משקיעים בבניית הזיכרון, רוצים שיהיה נגיש מכמה משטחי מוצר וממערכות, עם API נקי."],"points":[],"kind":"idea"},{"title":"התוצאות שהם רואים","body":["לפי לאמיס, מערכות זיכרון בייצור מביאות: דיוק טוב יותר, כי בפעם השנייה הסוכן עושה את המשימה טוב יותר אחרי שרשם מה השתבש. אחר כך מהירות ועלות: הסוכן מבזבז פחות טוקנים וקל לו יותר \"לעשות ב-shot אחד\", כי הוא יודע מה הוא עושה. והיא אומרת שזה משחרר קיבולת למפתחי מוצר להתמקד בניצחונות מוצר בזמן שהסוכנים מנהלים לולאת למידה. אלה טענות היצרנית מניסיונה, והתמלול לא כולל נתונים מספריים."],"points":[],"kind":"idea"},{"title":"צוואר הבקבוק החדש: זיכרון in-band","body":["כשהסוכן כותב וקורא זיכרון בתוך סשן, יש מגבלות: ראשית פיצול של מיקוד ומשאבים: מבקשים מהסוכן לבצע משימה וגם להשקיע בטיפוח זיכרון לעתיד. זו בעיית אופטימיזציה: כמה קיבולת הוא צריך להשקיע בגרסאות עתידיות של עצמו לעומת המשימה שביקשת, ויש גם חביון.","שנית, מגבלת נראות: הוא רואה רק את הסשן שלו, ולכן לא רואה דפוסים בין סשנים. כשאתם מתוסכלים שהסוכן חוזר על אותה טעות, הוא לא מבין כמה זה מתסכל כי בכל סשן יש לו חלון הקשר חדש. וכשמריצים צי סוכנים בסביבות שונות, כל סוכן לא יודע על כשלים של אחרים.","הפתרון: curation של זיכרון מחוץ לסשן (out-of-band). האנלוגיה: בית ספר עם הרבה תלמידים שמגישים עבודות, מורים שמסמנים, ומנהלת שסוקרת הכול. יש אנשים עם קיבולת ייעודית לעזור ללמוד, ויש מי שיש לו נראות על כל הצי ויכול לזהות דפוסים ולהתאים את תוכנית הלימודים."],"points":[],"kind":"idea"},{"title":"עיבוד לקחים ברקע (dreaming): איך זה עובד","body":["בנוסף לזיכרונות מתיישנים, צריך מעבר שבודק שכל מה שכתוב עדיין נכון. הם הציגו תהליך מסדר שני על זיכרון, שנקרא dreaming, ובדף נתייחס אליו כ\"עיבוד לקחים ברקע\". יש הקשר שהסוכנים מתייחסים אליו, תהליכי זיכרון שמאפשרים לסוכנים לנהל אותו בעצמם, ותהליך אצווה אסינכרוני שרץ עם משאבים משלו כדי לוודא שהזיכרונות עצמם יעילים ועדכניים.","במעשה: לוקחים מאגר זיכרונות קיים, ולוקחים סשנים או תמלילים של אינטראקציות מתקופה. נותנים את שניהם לסוכן שסוקר את התמלילים ואת המאגר ומזהה דפוסים שבהם אפשר לשפר את הזיכרון. הוא מוציא מאגר חדש או שינויים מוצעים. הוא יכול להוציא טוקנים על בעיה אחת: לזהות כשלים עקביים ולהציע שינויים כך שלמחרת הסוכנים ירגישו חכמים יותר.","דוגמאות מהאנלוגיה: המנהלת רואה שכל תלמיד טעה באותה שאלת גיאוגרפיה, ובודקת ורואה שנושא שלם חסר מתוכנית הלימודים, ומציעה שינוי. באלגברה כולם עונים ברדיאנים במקום מעלות, אז נותנים הוראה איך להגדיר את המחשבון. אצל סוכנים, זה זיהוי של קריאת כלי שנכשלת שוב ושוב בגלל תצורה. ועוד: דפוס ברמת הארגון, \"כולם משתמשים ביותר מדי מקפים ואתם לא אוהבים את זה\", אז מוסיפים הנחיה ארגונית.","היא מדגישה שבתמלילים בודקים לא רק את התשובות, אלא גם את קריאות הכלים וכל המטא־דאטה שמרכזי לביצועי הסוכן."],"points":[],"kind":"idea"},{"title":"ארכיטקטורה של תהליך כזה בייצור","body":["יש מאגר זיכרון (אוסף קבצי markdown מאורגנים בתיקיות). לוקחים מספר תמלילים (הלוך ושוב בין הסוכנים וגם מטא־דאטה על כלים ו-skills). ה-orchestrator פורס צי תתי־סוכנים שמנתחים את התמלילים. אפשר \"לכוון\" אותם: להגיד מה חשוב ומה לא בארגון הספציפי. ה-orchestrator סוקר את התגובות ומחליט איפה יש דפוסים נפוצים מספיק שמצדיקים שינוי.","אחר כך הוא מציע שינויים בודדים למאגר, ובמימוש שלהם בייצור הסוכן מוסיף רשימת תמלילים שבהם ראה את הדפוס, וסטטיסטיקות על שכיחות הבעיה ולמה זה מצדיק שינוי. האדם מחליט אילו שינויים לקבל ואילו לדחות."],"points":[],"kind":"idea"},{"title":"שני התהליכים במקביל, והעלות","body":["תהליך אחד: זיכרון in-band, שבו הסוכן כותב מה שחשוב. היתרון: בסשן הבא הסוכן כבר טוב יותר, זמן קצר לשינוי. החיסרון: משאבים מתחרים ונראות חלקית. והשני: עיבוד לקחים ברקע, out-of-band, עם נראות רחבה וקיבולת ייעודית, כלומר הוצאת טוקנים שמכוונת רק לעזור לסוכנים ללמוד.","\"זה נשמע יקר\". אבל, היא אומרת, בהתאם לשיפורים שרואים כשבונים מאגרי זיכרון יעילים, עלויות יורדות כי הסוכנים מצליחים יותר בניסיון אחד ויש להם את המידע הנדרש."],"points":[],"kind":"idea"},{"title":"סיכום וקריאה לפעולה","body":["בסיס: do the simple thing that works. ניהול הקשר עושה הבדל עצום. קובץ CLAUDE.md, skills, ואפשרות לסוכנים לנהל אותם בעצמם. כשמרחיבים לארכיטקטורות עם הרבה סוכנים וריצות ארוכות, להוסיף guardrails שמאפשרים ניהול זיכרון בטוח, ניתן לאימות ולביקורת. זה לא ייחודי לקוד: היא משתמשת בזיכרון גם בהכנת מצגות (איך היא אוהבת לכתוב, איך היא אוהבת שקופיות).","כדי לסגור את הלולאה, להוסיף תהליך out-of-band כמו dreaming שמאחד את הזיכרון, חותך מה שלא רלוונטי, מוסיף מה שחסר ומארגן. היא מסיימת: \"keep thinking, keep learning and keep dreaming\"."],"points":[],"kind":"idea"},{"title":"יש מימוש זיכרון שאת ממליצה עליו, משהו ארגוני?","body":"לאמיס מציינת שאסור להם לעשות קריאות לפעולה מוצרית, אבל מכיוון ששאלו: הארכיטקטורה מבוססת על תשתית הזיכרון שלהם ל-Claude Managed Agents. הגרסאות וה-hash קיימים ב-API של זיכרון ו-dreaming שלהם.","kind":"qa"},{"title":"איך מבטיחים שהתהליך ברקע מכבד הרשאות משתמשים שונים?","body":"כשמגדירים עבודת עיבוד, בוחרים אילו תמלילים לצרף, ולכן אפשר להתאים להרשאות של מאגר הזיכרון: לא חייבים לקחת הכול מתקופה מסוימת, אפשר לבחור תמלילים עם אותה הרשאה.","kind":"qa"},{"title":"האם אנחנו ממציאים מחדש מסדי נתונים מעקרונות ראשונים?","body":"היא אומרת שזה אכן חזרה לעקרונות הנדסת תוכנה: מצאו את הגבול בין אוטונומיה לבין דברים דטרמיניסטיים שבנויים ב-harness. \"יש לנו מספיק אותות לדעת שדברים כאלה צריך לעשות באופן דטרמיניסטי ואין צורך להמציא את הגלגל\".","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["מתחילים בפשוט: CLAUDE.md, skills, ומתן אוטונומיה לסוכנים.","זיכרון בייצור דורש גרסאות, מקביליות, הרשאות וניידות.","זיכרון בתוך סשן מוגבל בנראות ובקיבולת, ולכן יש מקום לתהליך עיבוד לקחים ברקע שמחוץ לסשנים.","גם בתהליך כזה האדם מאשר או דוחה שינויים."],"kind":"idea"}],"diagram":{"title":"שתי לולאות למידה: בתוך הסשן ומחוצה לו","type":"loop","nodes":[{"id":"session","label":"סשן סוכן","note":"קורא וכותב זיכרון תוך כדי עבודה (in-band)"},{"id":"store","label":"מאגר זיכרון","note":"קבצי markdown עם גרסאות והרשאות"},{"id":"transcripts","label":"תמלילי סשנים","note":"שיחה, קריאות כלים, מטא־דאטה"},{"id":"batch","label":"עיבוד לקחים ברקע","note":"תתי־סוכנים ו-orchestrator מנתחים דפוסים"},{"id":"review","label":"אישור אנושי","note":"קבלה או דחייה של שינויים מוצעים, עם סטטיסטיקות"}],"edges":[{"from":"session","to":"store","label":"כותב"},{"from":"store","to":"session","label":"נקרא"},{"from":"session","to":"transcripts","label":"נשמר"},{"from":"transcripts","to":"batch","label":"קלט"},{"from":"store","to":"batch","label":"קלט"},{"from":"batch","to":"review","label":"מציע"},{"from":"review","to":"store","label":"מעדכן"}]},"terms":[{"term":"Context engineering","en":"Context engineering","definition":"עבודה על ההקשר שהמודל מקבל כדי שיבצע משימות ספציפיות, ובכך מכפילה את האינטליגנציה של המודל."},{"term":"Progressive disclosure","en":"Progressive disclosure","definition":"טעינה הדרגתית: הסוכן קורא רק את ה-front matter ובוחר אילו חלקים לטעון."},{"term":"זיכרון in-band","en":"In-band memory","definition":"הסוכן קורא וכותב זיכרון בתוך הסשן שבו הוא עובד."},{"term":"עיבוד לקחים ברקע","en":"Dreaming","definition":"תהליך אצווה אסינכרוני מחוץ לסשנים שמנתח תמלילים של הרבה סוכנים ומציע שינויים בזיכרון."},{"term":"Hash לפני כתיבה","en":"Hash-based concurrency","definition":"בדיקה שהזיכרון לא השתנה בין הקריאה לכתיבה. אם השתנה, הסוכן קורא מחדש וכותב מחדש."}],"gaps":["התמלול נגמר אחרי שלוש שאלות קהל והמנחה מציין שנגמר הזמן.","שם המשפחה של הדוברת (Mukta) מופיע בכותרת בלבד. בהרצאה נאמר רק \"Lamis\".","ההפניה של שואל לדליפת קוד של Claude Code (\"Claude code leak\") היא של איש בקהל ולא אומתה.","אין נתונים מספריים לגבי שיפורי דיוק, מהירות ועלות."],"source_refs":["https://www.youtube.com/watch?v=tTcxVv8HHNw","https://github.com/AINativeDev/aidevcon-2026-ldn"]},{"number":38,"id":"libNzUdL9eM","url":"https://www.youtube.com/watch?v=libNzUdL9eM","type":"session","type_he":"סשן","duration":"32:05 דקות","title_he":"קוד לפי תחושה: זה הכי טוב שאנחנו יכולים?","speaker_he":"דייב פארלי","summary":"פארלי טוען שהשפה הטבעית לבדה לא מספיקה לתכנות עם AI. בעיות המפתח: איך מפרטים בדיוק, איך מאמתים שקיבלנו מה שרצינו, ואיך שומרים על עבודה הדרגתית. הפתרון המוצע: מפרטים ניתנים להרצה בסגנון BDD, בשפה ייעודית לבעיה, שרצים ב-pipeline ומאמתים את מה שה-AI יצר.","takeaways":["שפה טבעית לבדה אינה מספיקה.","מפרטים שניתנים להרצה שמורים בגרסאות.","בדיקות עצמאיות או מוסתרות עשויות לצמצם התאמה של הפתרון לבדיקה ידועה מראש.","ניתוח ופירוק בעיות הם המיומנות המרכזית."],"category":"מפרטים ותכנון","coverage":"כל התמליל הזמין נסקר עד סיום ההרצאה. אין שאלות מהקהל בתמליל. שם פרויקט שתומלל באופן לא ברור הושמט.","source_basis":"תמלול מלא של ההרצאה (כ-4,600 מילים). אין שאלות ותשובות בתמלול. הטקסט הרשמי תואם. לא נצפה בסרטון, והדוגמאות על המסך מתוארות לפי דברי הדובר.","lead":"פארלי טוען שהשפה הטבעית לבדה לא מספיקה לתכנות עם AI. בעיות המפתח: איך מפרטים בדיוק, איך מאמתים שקיבלנו מה שרצינו, ואיך שומרים על עבודה הדרגתית. הפתרון המוצע: מפרטים ניתנים להרצה בסגנון BDD, בשפה ייעודית לבעיה, שרצים ב-pipeline ומאמתים את מה שה-AI יצר.","chapters":[{"title":"הפתיחה: מה עמיד ומה פשוט טיפשי","body":["המנחה אומר שזו ההרצאה האחרונה של היום לפני המסיבה ומציג אותה כמבט על התהליכים והפרקטיקות של vibe coding ומה צריך להמשיך איתו. פארלי פותח: \"אני הדובר האחרון בינכם לבין הבירה, אז אנסה לא להאריך\". הוא מתעניין ב\"דברים שנראים עמידים\", גם כשמדברים על שינוי משבש כל כך כמו אימוץ AI לתכנות. הרבה התנהגויות עמדו במבחן הזמן, ולדבריו אחרים אמרו זאת היום.","הוא אומר שמה שיבוא יהיה שונה, \"שינוי עצום\", אבל מתחיל בהקשר פרובוקטיבי: חלק מהדברים שנאמרים הם \"פשוט טיפשיים\". הוא טוען ש-vibe coding, תכנות בשפה טבעית, יש להם מקום אבל הם גם \"רעיונות גרועים\". שניים נוספים: לפטר את כל המפתחים הג׳וניורים כי AI יכתוב הכול, וליצור בדיקות באמצעות AI: \"חלק נכונים, חלק רעיון איום, ויש הרבה niuance\" (כך אמר, בניסוח שלנו: \"יש בזה ניואנסים\")."],"points":[],"kind":"idea"},{"title":"למה בדיקות? מדידה, כמו סרגל של נגר","body":["פארלי מכריז שהוא \"מפתח TDD מהאסכולה הישנה\" ומתחיל מבדיקות. מה הן? לא הוכחת הצלחה, לא בדיוק מציאת טעויות, ובטח לא אתגר לגאונות המתכנת. לדעתו בדיקה היא סוג של מדידה: \"המקבילה של נגר עם סרגל בכיס\". משתמשים בבדיקות כדי לוודא שאנחנו עושים את הדברים הנכונים ושהם נשארים נכונים. אבל לשם כך צריך להגדיר מראש מהן המטרות, ולא אפשר להסיק מטרות מהפתרון כי הפתרון יכול תמיד להיות שגוי."],"points":[],"kind":"idea"},{"title":"למה בדיקות שנוצרות מהקוד הן ברובן רעיון טיפשי","body":["הדוגמה: פונקציה calculate tax שמחזירה 50 כפול הסכום. אם זו נקודת ההתחלה, כל מה שסוכן AI יכול לעשות הוא לכתוב בדיקה שמאשרת את הטעות שנכתבה בפונקציה: הקלט היחיד שלו הוא הקוד, ולכן הוא יאמת שהקוד עושה את מה שהקוד עושה. זה שימושי ל-refactoring, כלומר שינוי שמשמר התנהגות. אבל זה \"זבל\" אם רוצים לפתח מערכת חדשה ולוודא שהיא עושה את הדבר הנכון.","לכן, מי שמוכר לכם \"בדיקות AI בחינם שיבואו ויבדקו את המערכת הקיימת\" נותן ערך כלשהו, אבל לא את הערך של בדיקות אמיתיות בתהליך פיתוח. \"הן ברובן ׳קופ אאוט׳ לאנשים שלא רוצים להגדיר מטרות\". והגדרת המטרות היא התפקיד שלנו כמפתחים."],"points":[],"kind":"idea"},{"title":"בשביל מה תוכנית ושפות תכנות","body":["בשביל מה תוכנית? לא \"לקודד אלגוריתמים\" ולא ליישם את התכנון הגאוני שלי. זה לא הערך שבגללו משלמים לי. לשפות תכנות, לדעתו, שלוש מטרות: לארגן את החשיבה שלנו על בעיה ולחקור את שטח הפנים שלה, לתקשר את ההבנה שלנו לאנשים אחרים בצוות, ורק לבסוף לומר למחשב מה לעשות. \"הוראות אסמבלי אומרות למחשב מה לעשות מצוין, ובכל זאת מעטים כותבים אסמבלי\".","ושלוש טכניקות שגלומות בשפות תכנות: דקדוק פשוט ועקבי שמאפשר ביטוי מדויק וניתן להרצה, ביטוי חד־משמעי של כוונה, והרצה חוזרת ודטרמיניסטית: הרצה פעמיים עם אותם קלטים נותנת אותה תוצאה, וזה מאפשר לחשוב, לבדוק ולהבין."],"points":[],"kind":"idea"},{"title":"למה השפה הטבעית לא מספיקה","body":["פארלי מציין שמישהו אמר היום שהוא ציטט את Karpathy ש\"שפת התכנות של העתיד היא אנגלית\", והוא לא אוהב את הרעיון. שפה טבעית פתוחה לפרשנות, והוא מזכיר סיטואציות שבהן אדם מלמעלה נותן הוראה עמומה לצוות ואז מתאכזב מהתוצאה. כדוגמה הוא נותן את המשפט \"Time flies like an arrow\".","השוואה למטרות: לארגן חשיבה, השפה הטבעית עמומה מדי. לתקשר עם בני אדם, היא עמומה מדי. לומר למחשב מה לעשות, היא לא מספיק מדויקת: כשמבקשים משהו ברור כמו \"תממש FizzBuzz\" אפשר שיצא בצורה חוזרת, אבל בדרך כלל התוצאה תהיה מעט שונה בכל פעם. ושלוש הטכניקות: אין דקדוק פשוט ועקבי, אין חד־משמעות, אין חזרתיות ודטרמיניזם. ואפילו אם שומרים גרסאות של הפרומפט, זה לא מספיק כדי להגיע שוב לאותה תוצאה.","הוא מדגיש: \"Vibe coding לבדו פשוט לא מספיק\". אבל זה לא אומר שצריך לקרוא את כל הקוד או לעבוד רק בשפת תכנות. הוא עצמו לא כתב קוד ביד כבר זמן רב, כי סוכן ה-AI כותב הכול, אבל הוא מדויק יותר מאשר שפה טבעית רגילה: \"גרסה מדויקת ונורמטיבית של שפה טבעית\"."],"points":[],"kind":"idea"},{"title":"שלוש בעיות בתכנות עם AI","body":["הבעיה הראשונה: איך מפרטים בדיוק מה רוצים. השנייה: איך מאשרים שקיבלנו מה שרצינו, בעיית האימות. השלישית: \"אנחנו לא עובדים כמו המכונות והן לא עובדות כמונו\". בני אדם מתמודדים עם מגבלות של חלון ההקשר של הראש: יש תמונה כללית, ואז מתקדמים בשינויים קטנים, מעריכים כל חלק ועוברים לבא. לדעתו פיתוח תוכנה איכותי הוא תמיד תהליך הדרגתי של למידה וגילוי, ו\"כל ההנדסה כזו\".","מה עשינו? האצנו את חלק הקידוד, שהיה החלק הקל. זה מזיז את צוואר הבקבוק, כמו בספר The Goal ובתורת האילוצים. ובעצם צוואר הבקבוק היה כמעט תמיד אימות ושחרור והבנת מה באמת רוצים, ולא הקידוד, אם היינו טובים כמספקים.","ה-AI עובד אחרת: בונה תמונה והולך \"בום\" עם שינוי ענק. עד לאחרונה הוא כתב מחדש את כל המערכת בכל פעם, ואם לא הגדרנו מטרות הוא יכול לכתוב Space Invaders במקום מערכת בקרה. רבים מהמדברים על AI בקידוד מדברים ממערכות קטנות, בעוד הוא בונה מקצועית מערכות גדולות ומורכבות, ולבדוק אותן ידנית \"אפילו לא קרוב לספיק\"."],"points":[],"kind":"idea"},{"title":"הקצב: 12,000 שורות ביום","body":["פארלי מספר שדיבר עם מישהו שמאמץ בכל לב פיתוח עם כמה סוכנים וכותב משחק, והוא מעריך שהוא כותב 12,000 שורות קוד ביום. אף בן אדם לא יכול לסקור 12,000 שורות ביום ולא לבדוק ידנית את ההתנהגות. צריך להאיץ אימות והבטחת איכות לקצב היצירה, \"אחרת נסבול מבעיית תורת האילוצים\".","וזה, הוא אומר, בדיוק מה שעושים ב-continuous delivery: לציין מה רוצים בצורה ברורה ו\"ניתנת לשחזור\", ולאמת שוב ושוב אחרי כל שינוי. \"זה table stakes\"."],"points":[],"kind":"idea"},{"title":"הפתרון: תוכנית כתיאור מדויק של הבעיה","body":["בעבר תוכנית הייתה פתרון מדויק מקודד כאלגוריתמים, והבעיה נשארה בראש. בדוגמה: אלגוריתם ניתוב, כשהתוצאה הרצויה היא \"למצוא את הדרך הביתה\". בעתיד תוכנית תהיה תיאור מדויק של מה שרוצים, מקודד כמפרטים, שה-AI מתרגם להוראות ניתנות להרצה ומאמת שקיבלנו מה שרצינו. כלומר התוכנית זזה מפוקוס על פתרון לתיאור מדויק יותר של הבעיה.","זה סוג של פיתוח מונע מפרטים, והמפרט הוא בדיקות ניתנות להרצה שגם מגדירות מה רוצים וגם מאמתות שקיבלנו. לשם כך מתכננים שפה ייעודית לבעיה (domain specific language) ומפרטים בה את כל ההתנהגויות של המערכת, לא רק התנהגות משתמש רגילה: כמה מהר רוצים תוצאות, מה רמת האבטחה. אי אפשר לתת ל-AI להסיק זאת, כי רמת האבטחה תלויה בהקשר: משחק למשתמש יחיד מול בנק, \"תבזבזו מהנדסה על המשחק ותחסירו בבנק\"."],"points":[],"kind":"idea"},{"title":"איך מאמתים: מפרטים ניתנים להרצה והגנה מפני רמאות","body":["בעבר שפות עם טיפוסים אימתו חלק, וגם TDD. בעתיד מפרטים ניתנים להרצה הם גם אימות וגם מפרט. אפשר לעשות זאת בשפה אנושית: הוא מלמד את ה-AI לכתוב בדיקות בסגנון BDD שהוא אוהב, מפרט מה רוצה, וה-AI משלים את הפערים מתיאורים באנגלית יחסית פשוטה. ה-AI יוצר פתרונות שמתאימים למפרטים, ומריצים את הבדיקות נגדם. כדי שלא יזייף, נותנים לו ערכי בדיקה שלא ראה, ושומרים בדיקות מוסתרות.","הצעדים: המתכנת ממציא DSL לבעיה, מגדיר את כל ההתנהגויות כפרומפטים בצורת מפרטי BDD, וה-AI בונה תשתית בדיקות שמריצה אותם ומייצר קוד שממלא את כל המפרטים. אז יש הגדרה מדויקת של ההתנהגויות וגם אימות שהן התקבלו."],"points":[],"kind":"idea"},{"title":"להחזיר עבודה הדרגתית","body":["בעבר עבדנו בצעדים קטנים, מוסיפים בדיקות וקוד, מקבלים משוב ב-pipeline. בעתיד אותו דבר: ה-AI מייצר קוד, אוספים משוב לאימות כל שינוי, בונים בהדרגה בהרבה שינויים קטנים וערכים למידה אמפירית. \"אם התרגלתם ל-continuous delivery, הדברים קלים יותר\", והוא מציין ששניים מהדוברים שהיו היום אמרו זאת, לפחות במרומז.","לשם כך: מנהלים גרסאות של המפרטים (הם בעצם התוכנית), מריצים אותם ב-deployment pipeline, אחרת ה-AI יזייף, ומונעים מה-AI \"לשחק\" בבדיקות על ידי הסתרת חלק מהן. את רוב זה מתאר בדיוק איך acceptance testing עם BDD כבר עובד, ולכן \"זה צעד פשוט אם עבדתם כך\"."],"points":[],"kind":"idea"},{"title":"דוגמה: מתשוקה מעורפלת למפרט לדוגמאות","body":["הוא הראה דוגמה מקורס הדרכה (לא מערכת אמיתית): מערכת תכנון טיסות. התהליך: מתחילים מ\"משאלה מעורפלת\", עוברים לגרסה פורמלית יותר בצורת user story, ואז לדוגמאות שמראות שהפיצ׳ר קיים. אלה המפרטים הניתנים להרצה, והם גרמו לבניית מערכת שבפועל תכננה טיסות. הוא אומר שעשה זאת כמה פעמים בבניית מערכות אמיתיות."],"points":[],"kind":"idea"},{"title":"המסקנות: AI כמהדר, ולימוד פירוק בעיות","body":["המסקנות שלו: שפה טבעית לבדה לא מספיקה. שפות ייעודיות בסגנון BDD הן האלטרנטיבה הטובה ביותר ל-prompting יעיל, כי הן משלבות מפרט מדויק ואימות מובנה. יצירת בדיקות אוטומטית מהפתרון היא \"די בדיחה\", ניש עם שימוש מסוים אבל \"מקרה קצה\" שלא פותר את הבעיה האמיתית.","את כישורי הניתוח ופירוק הבעיות צריך להתייחס כאל \"הליבה האמיתית של הדיסציפלינה שלנו\": חשיבה על בעיה, פירוק, מקרי קצה והארכיטקטורה.","הוא רואה בכך הפעלה של \"שפת תכנות מהדור החמישי\", ו-AI דומה למהדר: \"לא נתעניין יותר בקוד שהוא מייצר, כי נאמת שקיבלנו את התוצאות. כמו המעבר מאסמבלי לשפה עילית\". הוא עצמו היה פעם מתכנת אסמבלי והציץ בקוד שמהדרים ייצרו, ולא עושה זאת שנים. ואם אפשר לאמת שההתנהגויות הרצויות הן אלה שקיבלנו, \"למי אכפת מהמימוש\". בסוף הוא מפנה לפרויקט קוד פתוח שמיישם את החשיבה הזו (שמו בתמלול \"NYSE\", האיות לא ברור)."],"points":[],"kind":"idea"},{"title":"מה נשאר מהסשן","body":[],"points":["שפה טבעית לבדה עמומה ולא דטרמיניסטית, ולכן לא מספיקה לתכנות.","בדיקות שנוצרות מהקוד רק מאשרות את הקוד. המטרות צריכות להגיע מאדם.","הפתרון: מפרטים ניתנים להרצה, בגרסה מבוקרת, בתוך pipeline, וחלק מהבדיקות מוסתרות מה-AI.","אם התנהגות מאומתת, אפשר לדעת פחות על הקוד, כמו המעבר מאסמבלי לשפה עילית."],"kind":"idea"}],"diagram":{"title":"משפה טבעית עמומה למפרט שניתן להרצה","type":"flow","nodes":[{"id":"wish","label":"משאלה מעורפלת","note":"נקודת ההתחלה"},{"id":"story","label":"User story","note":"גרסה פורמלית יותר"},{"id":"examples","label":"דוגמאות מפרט (BDD)","note":"בשפה ייעודית לבעיה"},{"id":"ai","label":"AI מייצר קוד ותשתית בדיקות","note":"התוכנית היא המפרט"},{"id":"pipeline","label":"Pipeline מריץ","note":"כולל בדיקות שה-AI לא ראה"},{"id":"feedback","label":"משוב ושינוי קטן","note":"עבודה הדרגתית"}],"edges":[{"from":"wish","to":"story","label":"מתפרט"},{"from":"story","to":"examples","label":"דוגמאות"},{"from":"examples","to":"ai","label":"קלט"},{"from":"ai","to":"pipeline","label":"נבדק"},{"from":"pipeline","to":"feedback","label":"תוצאה"},{"from":"feedback","to":"examples","label":"משפר מפרט"}]},"terms":[{"term":"BDD","en":"Behavior-driven development","definition":"כתיבת מפרטים של התנהגות בשפה קרובה לאנגלית שהופכים לבדיקות קבלה."},{"term":"Executable specification","en":"Executable specification","definition":"מפרט שהוא גם בדיקה שאפשר להריץ: מגדיר מה רוצים ומאמת שקיבלנו."},{"term":"DSL ייעודי לבעיה","en":"Domain-specific language","definition":"שפה קטנה שמתאימה לבעיה ספציפית כדי לבטא התנהגויות בדיוק."},{"term":"תורת האילוצים","en":"Theory of Constraints","definition":"הרעיון שהאצת חלק אחד מזיזה את צוואר הבקבוק לחלק אחר. כאן: האצת הקידוד מזיזה את הלחץ לאימות."},{"term":"Continuous delivery","en":"Continuous delivery","definition":"עבודה בצעדים קטנים עם אימות מהיר ובלתי פוסק אחרי כל שינוי."}],"gaps":["אין שאלות ותשובות. התמלול נגמר בסיום הדובר ובתודה.","שם פרויקט הקוד הפתוח בסוף נשמע \"NYSE\" בתמלול ולא אומת.","הערכת 12,000 שורות ביום היא של אדם אחר שפארלי מצטט."],"source_refs":["https://www.youtube.com/watch?v=libNzUdL9eM","https://github.com/AINativeDev/aidevcon-2026-ldn"]},{"number":39,"id":"ItTJpQz35CY","url":"https://www.youtube.com/watch?v=ItTJpQz35CY","type":"session","type_he":"סשן","duration":"30:54 דקות","title_he":"נבנה לבני אדם. עכשיו הגיעו הסוכנים.","speaker_he":"דנה לוסון · Netlify","summary":"דנה לוסון מציגה את הטענה ש\"עיצוב לסוכנים\" הוא גם עיצוב לבני אדם. היא מספרת על חברה, מטפלת בעיסוי, שבנתה אפליקציה בלי לדעת מה זה Git, מגדירה AX כמשמעת שמאחדת UX ו-DX, ומציגה שלושה מעברים ארכיטקטוניים ושלושה עקרונות אמון.","takeaways":["הפרסונה של הבונה התרחבה.","מערכות ישנות חייבות להתפתח.","בטיחות היא יסוד.","לספק שגיאות מובנות, אירועים וארכיטקטורה קריאה."],"category":"מוצר וארגון","coverage":"שוחזר מכתוביות (עד כ-1849 שניות), כולל שאלות ותשובות.","source_basis":"תמלול מלא עם חותמות זמן (כ-6,400 מילים), שהוחלף לגוף ההרצאה במקום הגוף החסר בקובץ המקור, כולל שתי שאלות קהל. הטקסט הרשמי קיים ומתאים. לא נצפה בסרטון.","lead":"דנה לוסון מציגה את הטענה ש\"עיצוב לסוכנים\" הוא גם עיצוב לבני אדם. היא מספרת על חברה, מטפלת בעיסוי, שבנתה אפליקציה בלי לדעת מה זה Git, מגדירה AX כמשמעת שמאחדת UX ו-DX, ומציגה שלושה מעברים ארכיטקטוניים ושלושה עקרונות אמון.","chapters":[{"title":"פתיחה: \"אנחנו לא יקרים יותר\"","body":["המנחה מציג את דנה כ-CTO של Netlify ואומר שנטליפיי בנתה תוכנה שנים עבור עולם \"בלי סוכנים\" ועכשיו יש סוכנים. דנה מתחילה בבדיחה על כך שהגיעה אתמול ללונדון ו\"הפכה לאוהדת ארסנל\", ואומרת שהיא עם ג׳ט לג וקפאין.","היא אומרת ש-Netlify היא פלטפורמת אפליקציות ווב אג׳נטית שעוזרת לכל אחד לבנות, לפרוס וליצור חוויות. והעולם משתנה כל כך מהר שההרצאה עלולה להיות \"מעט לא עדכנית\"."],"points":[],"kind":"idea"},{"title":"פרסונת הבונה השתנתה","body":["היא שואלת כמה אנשים בחדר מזדהים כמפתחים, ואומרת: \"אנחנו כבר לא יקרים\" (we ain't precious no more). המשתמשים של הפלטפורמות שלנו הם כבר לא רק מפתחים. אנחנו עדיין בונים, אבל לא היחידים: עם סוכנים כל אחד יכול להשתתף.","היא מצטטת תחזית של IDC שיבנו יותר מ-500 מיליון אפליקציות חדשות עד 2028, יותר מארבעים השנים הקודמות יחד, ומוסיפה שהיא עצמה יוצרת אחת ביום. לדבריה זה לא בגלל שמספר המהנדסים גדל אלא כי \"סוכנים הפכו כוונה לשפת תכנות\" ו\"שפת התכנות החזקה בעתיד היא אנגלית\". הנתון נאמר על ידה כציטוט ולא אומת."],"points":[],"kind":"idea"},{"title":"הסיפור של טוריה: מטפלת בעיסוי שרוצה אפליקציה","body":["דנה מציגה את חברתה הטובה טוריה (כך נשמע השם בתמלול), מטפלת מורשית בעיסוי, מתופפת ו\"היפית של ברנינג מן\". החלום: לא סתם אתר אלא חוויה מלאה לריטריט עיסוי בברבדוס, עם קהילה, תשלומים ותוכן. היא לא כותבת קוד אלא \"כוונות\". היא לא רוצה Wix.","טוריה פתחה את אפליקציית הצ׳אט האהובה עליה ותארה את החזון, והסוכן התחיל לבנות. אבל כל ההנחות שמוטמעות בכלים התבררו כהנחות אנושיות. היא נתקעה קודם כול ב-Git: היא לא ידעה מה זה. דנה, שעבדה ב-GitHub, אמרה לה \"את לא צריכה לדעת מה זה Git\".","המסקנה: \"הסוכנים עדיין מדברים שוטף שפת מפתחים, אבל לבני האדם שהם משרתים אין את זה\". הכלים הניחו רמת אוריינות טכנית שרוב העולם לא מחזיק."],"points":[],"kind":"idea"},{"title":"פרדוקס ה-AX: לתקן לטוריה זה תיקן גם למפתחים","body":["מה שהפתיע ב-Netlify בעיצוב מחדש לסוכנים: התיקון לטוריה תיקן גם למפתחים מנוסים. כשהם הבהירו הודעות שגיאה לסוכנים, בנו פלט build מובנה למכונות והסירו חיכוך מיותר, גם המפתחים הרוויחו. \"כל הנחה אנושית שהסרנו שיפרה את הפלטפורמה לכולם\". זו הפער ש-Netlify קוראת לו agent experience (AX).","דנה מספרת שיעצה לטוריה לא לדאוג מ-Git או פריסה: \"פשוט תנסחי את החזון ואני מטפלת בשאר\". הסוכן מטפל ב-Git, בפריסה וב-DNS, והבונה מתמקד בחזון. היא מציינת שאחרי עשרות שנים של בניית guardrails שימנעו מבני אדם לשבור ייצור, \"עכשיו מסירים אותם ואומרים: בואו ליצור\". ב-Netlify לסוכנים יש גישה מלאה לפרימיטיבים של הפלטפורמה: פורסים, מגדירים ומחדדים כך שהאדם לא נוגע בכלום. \"די מפחיד, נכון?\""],"points":[],"kind":"idea"},{"title":"הטענה המרכזית: UX ו-DX מתאחדים ל-AX","body":["היא משרטטת את ההיסטוריה: user experience, אחר כך developer experience (שנטבע ב-2012 על ידי Jeremiah Lee מ-Spotify, לפי דבריה), ואז הבוס שלה, Matt Biilmann (בתמלול כתוב \"Matt Billmann\"), אמר בשנה שעברה שהפרדיגמה החדשה היא agent experience. UX ו-DX \"מתאחדים לדיסציפלינה אחת\".","הסיבה: הבונה כבר לא אתה. הסוכנים עושים את העבודה הכבדה. כשחושבים איך משתמש קצה מתקשר, הוא גם סוכן. כשחושבים איך מפתח מתכנת על הפלטפורמה, זה סוכן. ובצד השני יושב אדם שמדבר אנגלית פשוטה ומצפה שזה פשוט יעבוד. \"AX זה לא להפיק שמחה למכונות אלא להסיר חיכוך בכל צעד כדי לעבור מרעיון למציאות בכמה פרומפטים\".","דוגמאות: שגיאות מובנות שסוכנים יכולים לפרסר ומהנדסים מבינים מהר יותר, ו-deploy previews שנותנים לסוכנים אותות ברורים של הצלחה או כישלון. AX, היא אומרת, קשור לתכנון משותף של בני אדם וסוכנים והחשבה מחדש על כל ה-stack: איך מבטאים כוונה, איך מערכות מתקשרות, ואיך אפשר לסמוך."],"points":[],"kind":"idea"},{"title":"הנוף: \"הרתמות על רתמות על רתמות\"","body":["בשנתיים האחרונות היה פיצוץ בכלי פיתוח מבוססי AI או \"harnesses\" (\"קראו להם איך שתרצו, השם ישתנה הרבה פעמים\"). היא צוחקת ש-Netlify היא \"harness על harness על harness, כל כך מטא\". מזכירה את Claude Code, Cursor ו-Windsurf, v0, Bolt של StackBlitz, Lovable, ו-GitHub Copilot עם מצבי agent שעובדים על issues ושולחים PRs.","רעיון ה-software factory קיים שנים, אבל עם סוכנים אפשר ליישם אותו. כולם חולקים דפוס: כוונה כקלט, תוכנה עובדת כפלט, והם צריכים תשתית שמבינה דפוסים, יעדי פריסה, CI ורשתות קצה. \"ואת זה אנחנו בונים ב-Netlify\"."],"points":[],"kind":"idea"},{"title":"שלושה שינויים במחזור חיי הפיתוח","body":["הראשון: מ-specs לכוונה. עדיין משתמשים ב-specs בפלטפורמות גדולות, אבל למשתמש הממוצע \"האינטרנט הוא אוסף אפליקציות ואתרים, לא כל כך קשה\". תהליך מסורתי מתחיל ב-PRD, עובר לכרטיס Jira או Linear. תהליך AI native מתחיל בפרומפטים, תיאורי בעיה, סקיצות והפניות: \"אני רוצה ריטריט בריאות עם הזמנות, לא מסמך דרישות של 50 עמודים\". ב-Netlify הם עושים dogfooding עם כלי בשם agent runners: הכוונה יוצרת קוד, והפלט עובר מיד לתהליכי הנדסה אמיתיים (preview deploys, בדיקות אוטומטיות, ייצור). \"מה שלקח מיליוני דקות לוקח שניות\".","השני: ממסירות סדרתיות ליצירה משותפת. היה מרוץ שליחים: PM כותב spec, מעביר לעיצוב, מעביר להנדסה, QA ואז DevOps \"כי אף אחד לא סומך על אף אחד שילחץ על הכפתור\". זה לקח שבועות. עכשיו צוותי מוצר יוצרים אבות־טיפוס עם סוכנים, מעצבים משנים את החוויה ישירות בקוד, ומהנדסים מאמתים ארכיטקטורה וכותבים guardrails (context specs, recipes, \"נקרא להם skills בשביל הנוחות\"). זמן המחזור יורד משבועות לשעות.","השלישי: מ-CI פסיבי ללולאות פיתוח אוטונומיות. הסוכנים לא רק כותבים קוד אלא משתתפים בכל מחזור החיים: מייצרים בדיקות, מזהים previews שנכשלו, מנתחים לוגים, מציעים תיקונים ופותחים PRs. ב-Netlify, כשנכשל build, הסוכן קורא את הלוגים, מאבחן שורש ומגיש תיקון בלי אדם בלולאה. \"זה לא עתיד, זה קורה כל יום\"."],"points":[],"kind":"idea"},{"title":"דוגמה קונקרטית: לוגי build מובנים","body":["לוגי ה-build שלהם היו נרטיב קריא לבני אדם, מצוין ל-DevOps ולא לסוכנים: \"זו לא שפת בני אדם, זו שפת לוגים, וזה גרוע יותר\". הם הוסיפו קודי שגיאה מובנים וקריאים למכונה לצד הטקסט האנושי. כך סוכן יכול לפרסר כשל build, לזהות תלות חסרה ולתקן אוטומטית. אותו פלט מובנה שיפר גם את הדשבורד למהנדסים: קטגוריות שגיאה במבט, סיבות כשל. \"אני לא סומכת על סוכנים ב-100%, בטח לא על ה-clawbot שלי, הוא די שונא אותי\"."],"points":[],"kind":"idea"},{"title":"המציאות: מערכות קיימות ומקוטעות","body":["בעולם מושלם של greenfield היה קל. אבל רובנו מכניסים סוכנים למערכות מקוטעות קיימות: אוספי API, מיקרו־שירותים וצינורות CI שתוכננו לאופרטורים אנושיים. סוכנים לא רואים בין גבולות שירותים, כל API מדבר ניב אחר, ותהליכים קריטיים חיים בידע שבראש של מישהו, ב-thread של Slack מ-2022 או במודול Terraform לא מתועד. \"כשסוכנים לא יכולים לצפות במערכת, הם לא יכולים לפעול בחוכמה\". אי אפשר \"להדביק\" סוכנים על ארכיטקטורה ישנה, האדריכלות עצמה צריכה להתפתח."],"points":[],"kind":"idea"},{"title":"שלושה שינויים ארכיטקטוניים: capabilities, אירועים וקריאות","body":["מ-API ל-capabilities: מערכות מסורתיות חושפות endpoints. סוכן שמסתכל על משטח API של 200 endpoints צריך להבין הקשר, סדר ופרמטרים. מערכות agent native חושפות פעולות ברמת כוונה: \"Create a site\", \"deploy repository\", \"provision edge compute\". ב-Netlify הרחיבו את ה-API לשני מצבים (REST רגיל ו-capabilities לסוכנים), וגם את ה-CLI, שלא יכול לבקש מפרמטרים \"yes, no, next\" מהסוכן.","מ-request-response לאירועים: API מסורתיים הם pull. סוכנים צריכים למשוך, לנחש ולנסות שוב. מערכות AI native חושפות אירועים כמו deploy started או PR created, והסוכנים נרשמים ופועלים. אין צורך ב-Kafka דווקא. מערכת ה-build של Netlify כבר פולטת אירועים בכל פריסה, והסוכנים הם אלה שצופים ולא בני אדם.","והחשוב ביותר: הפיכת הארכיטקטורה לקריאה לסוכנים. מערכות מבוזרות רצות על ידע שבראש. ב-Netlify יצרו מערכת תיעוד שנקראת blueprints: skills, הקשר ו-recipes, \"קבצי markdown בסגנון CLAUDE.md/AGENTS.md\" ורשומות החלטות ארכיטקטורה, כדי שסוכני קוד יבינו את המערכת לפני שהם משנים. \"המטרה היא לא תיעוד טוב יותר אלא לוודא שסוכנים יכולים לפעול בבטחה במערכות מורכבות\"."],"points":[],"kind":"idea"},{"title":"שלושה עקרונות אמון","body":["הכוח מגיע עם אחריות, כשסוכנים יכולים לפרוס קוד, להקצות תשתית ולשנות מערכות ייצור. האמון חייב להיות ברירת מחדל, לא אופציה. שלושה עקרונות ב-Netlify: (1) הרצה ב-sandbox: סוכנים לא יכולים לברוח ממנו ולגשת למשאבים שלא ניתנו. (2) אדם בלולאה כברירת מחדל: \"הסוכן בונה, האדם מאשר\", והמטרה לעשות את האדם החלק המשמעותי. (3) audit ו-rollback: כל פעולת סוכן נרשמת, ו\"היום הרבה קוד לא נשמר ב-Git, וזה פשוט מטורף\". צריך מערכת רישום כדי לבטל. \"אם אתה לא יכול להסביר מה הסוכן עשה, למה לסמוך עליו בייצור?\""],"points":[],"kind":"idea"},{"title":"ההשפעה הארגונית וארבעה לקחים לאימוץ מחר","body":["כשסוכנים מורידים את הסף לבנייה, כל החברה משתתפת: אבות־טיפוס, בדיקת השערות, כלים פנימיים ופתרונות ללקוחות. מנקודת מבט של איש DevOps, זה \"החלום שלי 20 שנה: build it yourself, ואני עובדת על הבעיות הקשות\". ההנדסה מתפתחת מלממש כל פיצ׳ר לוודא שיש guardrails, ארכיטקטורה הדוקה, ו-skills/recipes/context שעובדים.","ארבעת הלקחים: (1) הפרסונה של הבונה התרחבה, ולכן לעצב עבורה. (2) מערכות ישנות חייבות להתפתח: מ-API ל-capabilities ברמת כוונה. (3) בטיחות ואמון הם יסוד: sandbox, בקרה אנושית, ו-audit. (4) מה אפשר לשלוח מחר: לתקן שגיאות מובנות, ליצור אותות מבוססי אירועים, וארכיטקטורה קריאה. ו\"תלמדו לכתוב skills כי המשרה שלכם תלויה בזה\"."],"points":[],"kind":"idea"},{"title":"הסיום: כשהקוד כבר לא המשאב הנדיר","body":["דנה מצטטת את Matt Biilmann: כשכל אחד יכול לייצר תוכנה, קוד אינו המשאב הנדיר. במשך עשורים צוואר הבקבוק היה כתיבת קוד, מציאת מהנדסים ושליחת פיצ׳רים, והוא מתמוסס. נדירים עכשיו: טעם (מה שווה לבנות), שיקול דעת (מתי לשלוח) וארכיטקטורה (תכנון מערכות בקנה מידה). AX גם אילץ אותם להבהיר את הארכיטקטורה והאותות שלהם, וכך שיפר אותם כמפתחים.","חזרה לטוריה: במערכת שתוכננה לסוכנים, היא עקפה את כל המכשולים: גררה את הכוונות שלה ל-Netlify והכול עבד. בלי Git, בלי CLI ובלי תצורות פריסה. הסוכן טיפל בהכול. היא התקשרה ואמרה \"Girl, I am a developer\". \"לא בניתי את האתר, היא בנתה\". דנה אומרת שזו חוויה אנושית ולא רק חוויית סוכן, ומפנה ל-netlify.com/ax. המסקנה: \"מעצבים מחדש לכולם, לא רק לסוכנים. זכרו מי אתם משרתים\"."],"points":[],"kind":"idea"},{"title":"מתי מדברים על מה לא לבנות ועל ההשפעה הסביבתית והמורכבות של 500 אלף האפליקציות?","body":"דנה: זה האתגר. \"האמת המרה: תבנו הרבה דברים שיהיו מיושנים בחודשים ולא בשנים\", ויש הרבה \"slop\" שיהיה נטל על משאבים. כמהנדסים אנחנו צריכים לשאת באחריות ליישם דחיסה וכו׳ כדי לשמור על אינטרנט פתוח ודמוקרטי וגם ידידותי לסביבה. היא ממליצה למי שמתחיל להתמקד בפנימיות וברקע של מדעי המחשב.","kind":"qa"},{"title":"איפה האחריות כשהאבסטרקציה מסתירה את מה שמתחת?","body":"\"Push and pull\". לקהל שרוצה לבנות אתרים Netlify לוקחת את כל האחריות וההקשר, ובארגונים גדולים יש מישור בקרה (policy engines, control panels) ל-CISO או ל-R&D. הרבה מוסתר כי \"האינטרנט הוא אוסף אפליקציות ואתרים, בעיקר JavaScript ובסיס נתונים\". בארגונים, אחריות היא ממשל, מדיניות וזהות; לחובבים רק שיעבוד.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["עיצוב לסוכנים משפר גם את חוויית בני האדם: שגיאות מובנות, אירועים וארכיטקטורה קריאה.","המשתמש בפלטפורמה הוא כעת בן אדם עם כוונה, שמולו עומד סוכן.","אמון הוא ברירת מחדל: sandbox, אדם בלולאה, audit ו-rollback.","כשקוד לא נדיר, נדירים טעם, שיקול דעת וארכיטקטורה."],"kind":"idea"}],"diagram":{"title":"מעבר מ-DX ל-AX: מי משתמש בפלטפורמה","type":"layers","nodes":[{"id":"human","label":"בן אדם עם כוונה","note":"מטפלת, מורה, בעל עסק קטן"},{"id":"agent","label":"סוכן","note":"מבצע Git, פריסה, DNS"},{"id":"platform","label":"פלטפורמה ידידותית לסוכן","note":"שגיאות מובנות, אירועים, capabilities"},{"id":"bp","label":"Blueprints","note":"skills, הקשר ומתכונים"},{"id":"trust","label":"אמון","note":"sandbox, אדם בלולאה, audit ו-rollback"},{"id":"preview","label":"Deploy preview","note":"האדם רואה ומחדד"}],"edges":[{"from":"human","to":"agent","label":"כוונה"},{"from":"agent","to":"platform","label":"פועל"},{"from":"bp","to":"agent","label":"מסביר את המערכת"},{"from":"platform","to":"preview","label":"יוצר"},{"from":"preview","to":"human","label":"משוב"},{"from":"trust","to":"platform","label":"מגביל"}]},"terms":[{"term":"Agent experience (AX)","en":"Agent experience","definition":"משמעת עיצוב שבה פלטפורמות מתוכננות כך שסוכנים יוכלו להשתמש בהן והבן אדם שמאחוריהם ייהנה ממנה: איחוד של UX ו-DX."},{"term":"Capabilities","en":"Capabilities","definition":"פעולות ברמת כוונה (יצירת אתר, פריסה) שסוכן יכול להבין במקום רשימת endpoints."},{"term":"Blueprints","en":"Blueprints","definition":"מערכת תיעוד של Netlify: skills, הקשר ו-recipes בקבצי markdown, כדי שסוכנים יבינו את המערכת לפני שינוי."},{"term":"Software factory","en":"Software factory","definition":"קו ייצור תוכנה שבו סוכנים מבצעים את מרבית העבודה."},{"term":"Deploy preview","en":"Deploy preview","definition":"כתובת ייחודית לכל שינוי שבה האדם מסתכל על התוצאה ומחדד."}],"gaps":["התמלול נגמר אחרי שתי שאלות קהל וסיום המנחה. אין שאלות נוספות.","הנתון של IDC (500 מיליון אפליקציות עד 2028) נאמר כציטוט של דנה ולא אומת.","שמות (טוריה, Matt Biilmann, Jeremiah Lee) נשמעים מהתמלול והאיות לא אומת.","בטקסט הרשמי ובקובץ ההתאוששות יש הבדלי ASR קלים. נוסח הדף מבוסס על הקובץ המלא עם חותמות הזמן."],"source_refs":["https://www.youtube.com/watch?v=ItTJpQz35CY","https://github.com/AINativeDev/aidevcon-2026-ldn"]},{"number":40,"id":"akZ85mG5HXY","url":"https://www.youtube.com/watch?v=akZ85mG5HXY","type":"other","type_he":"תוכן נוסף","duration":"9 שעות ו־25 דקות","title_he":"AI Native DevCon לונדון 2026: ההקלטה המשותפת","speaker_he":"מארגני הכנס וגיא פודז׳רני","summary":"זהו תמליל חלקי של ההקלטה המשולבת: פתיחת הכנס ותחילת ההרצאה של גיא פודז׳רני. החלק הזמין מציג את ההקשר והמיומנויות כרכיבי תוכנה שצריכים בדיקות, אבטחה וניהול מחזור חיים. אין כאן סיכום של יתר ההקלטה.","takeaways":["הנאמר כאן מתייחס רק לפתיחה ולחלק ראשון של ה-keynote.","Guy: skills דורשים את אותה משמעת כמו קוד.","הרצאות הכנס עצמן מסוכמות בנפרד, ולא מההקלטה הזו."],"category":"תוכן נוסף","coverage":"חלקי בלבד. התמלול הזמין (כ-50KB) כולל את פתיחת הכנס ואת תחילת ה-keynote של Guy, ונקטע באמצעו בחלק ה-observability ('extract real world eval scenarios'). שאר ההקלטה בת כ-9 שעות לא כוסה. אין לטעון כיסוי מלא ואין להחליף בהרצאות הבודדות.","source_basis":"","lead":"זהו תמליל חלקי של ההקלטה המשולבת: פתיחת הכנס ותחילת ההרצאה של גיא פודז׳רני. החלק הזמין מציג את ההקשר והמיומנויות כרכיבי תוכנה שצריכים בדיקות, אבטחה וניהול מחזור חיים. אין כאן סיכום של יתר ההקלטה.","chapters":[{"title":"פתיחת הכנס: ללמוד גם בין ההרצאות","body":"המנחה מציג שלושה מסלולים, סדנאות, ייעוץ טכני ומפגשים בין המשתתפים. האפליקציה שימשה אז ללוח זמנים, רישום והחלפת קשרים. אלה הנחיות היסטוריות לכנס שכבר נערך, לא הוראות שימוש או זמינות עדכנית. העיקרון הלימודי הוא לשלב הרצאות עם שיחות על בעיות אמיתיות וניסוי מעשי לאחר הכנס.","points":[],"kind":"idea"},{"title":"תמלולים כמקור לשיחה וללמידה","body":"המארגנים מסבירים שבמהלך הכנס נוצרו תמלולים עם Granola ומהם חבילות ידע ברישום של Tessl. המטרה שהוצגה היא לאפשר שאלות המשך והעמקה אחרי ההרצאה. הדבר מסביר את קיום מאגר הטקסט הרשמי, אבל אינו מוכיח שכל הקלטת היום נמצאת במאגר או שהתמלול מושלם.","points":[],"kind":"idea"},{"title":"גיא: מחסנית חדשה לפיתוח","body":"בחלק ההרצאה הזמין גיא מציג מודל, כלים, הקשר ומעטפת ביצוע. כלים מבצעים פעולות או חישוב באופן יעיל; ההקשר מלמד מדיניות, מפרטי מוצר וזרימות עבודה; המעטפת מוסיפה בקרות קבועות. אפשר להרכיב מהם קווי עבודה, אך אין להסיק מכך שהם אמינים בלי בדיקה.","points":[],"kind":"idea"},{"title":"מה נטען, מתי, ולמה","body":"גיא מבדיל כללים שנטענים תמיד, מיומנויות לפי צורך ומסמכים זמינים לחיפוש. הוא מדגים רעיונית הרכבה של מיומנויות וכלים לתגובה לתקרית. ככל שהידע משותף וניתן לשימוש חוזר, הוא מתנהג יותר כמו ספרייה ופחות כמו הודעה חד-פעמית.","points":[],"kind":"idea"},{"title":"שלוש בעיות ניהול","body":"אבטחה וממשל דורשים לדעת מה הותקן ומי משתמש בו. שימוש חוזר ללא מדד איכות יכול ליצור מאגר מלא כפילויות שאף אחד לא סומך עליו. תחזוקה נחוצה משום שמודל, API ותשתית משתנים, ומיומנות ישנה עלולה להנחות לפעולה שגויה. הנתונים הכמותיים הם דברי המרצה ולא בדיקה עצמאית.","points":[],"kind":"idea"},{"title":"בדיקות סטטיות ובדיקות ריצה","body":"גיא מבדיל בדיקת מבנה ותוכן ללא הפעלה, לבין הערכה שמריצה משימה בסביבה ושופטת תוצאה. הוא מציע רמות של מיומנות יחידה, הקשר פרויקט ומערכת רחבה. איכות תרחיש חשובה יותר מספירת בדיקות, וצריך קו בסיס כדי לזהות נסיגה או תרומה.","points":[],"kind":"idea"},{"title":"אבטחה, גרסאות ותלויות","body":"בהמשך הוא מתאר סריקות אבטחה, בדיקות התנהגות, ניהול גרסאות ורישום תלויות. כך ניתן לדעת איזו גרסה הותקנה, להפיץ תיקון ולשמור סף איכות. אלו עקרונות שהוצגו בהרצאה, לא בדיקת יכולות עכשווית של המוצרים שהוזכרו.","points":[],"kind":"idea"},{"title":"הטקסט נקטע בתחילת התצפיות","body":"החלק האחרון הזמין מציג תצפיות על ריצות סוכנים כמקור לתרחישי הערכה אמיתיים. המשפט נקטע בזמן תיאור חילוץ תרחישים, ולכן אין כאן סיום ההרצאה ואין סיכום של יתר ההקלטה בת יותר מתשע שעות. את ההרצאות העצמאיות יש לקרוא בעמודים הייעודיים שלהן.","points":[],"kind":"idea"}],"diagram":{"title":"החלק שנמצא בתמלול","nodes":["פתיחת הכנס","חלק מהרצאת גיא","קטיעה לפני סוף ההרצאה"],"note":"ההמחשה מתייחסת רק לטקסט הזמין, לא להקלטה המלאה."},"terms":[],"gaps":["חלקי בלבד. התמלול הזמין (כ-50KB) כולל את פתיחת הכנס ואת תחילת ה-keynote של Guy, ונקטע באמצעו בחלק ה-observability ('extract real world eval scenarios'). שאר ההקלטה בת כ-9 שעות לא כוסה. אין לטעון כיסוי מלא ואין להחליף בהרצאות הבודדות."],"source_refs":["https://www.youtube.com/watch?v=akZ85mG5HXY"]},{"number":41,"id":"4d3-Zrmf9Wo","url":"https://www.youtube.com/watch?v=4d3-Zrmf9Wo","type":"session","type_he":"סשן","duration":"36:39 דקות","title_he":"למה קשה למדוד סוכנים, ואיך בודקים זאת","speaker_he":"סימון אובסטבאום ורוב וילובי","summary":"שני מציגים מציעים שתי זוויות למדידה בעידן הסוכנים. סיימון מתאר מחקר רחב מסטנפורד על כ-150 אלף מהנדסים, שבו פאנל מומחים (ומודל שלמד לחקות אותו) מעריך את הקוד, ומראה שהשימוש ב-AI פוגע בצוותים ובפרטים בצורה לא אחידה. רוב מציג בדיקה ממוקדת של skills: האם הסוכן עוקב אחרי הוראות, באילו קטגוריות skill עוזר, ואיך למדוד אותו. בסוף יש שבע שאלות קהל.","takeaways":["למדוד תוצר ולא פעילות.","הפער בין משתמשי AI בולט וגדל.","skills הכי עוזרים בקונבנציות מקומיות ובמידע חדש.","למדוד גילוי, מסלול ותוצאה."],"category":"אימות ואיכות","coverage":"כל התמליל הזמין נסקר, כולל שאלות הקהל. נתונים מספריים לא ברורים בתמלול לא נכללו; תוצאות המחקר הן דברי הדוברים, לא אימות עצמאי.","source_basis":"תמלול אוטומטי יחיד, עם עיוותי ASR קשים בכל ההרצאה. אין התאמה בטקסט הרשמי (בדקנו, חפיפה זניחה). תחילת הקובץ היא הודעת מנחה על skill ה-granola של Tessl ועל סדנאות, לא חלק מההרצאה. רק רעיונות ברורים נכללו. מספרים לא ברורים הושמטו או סומנו. לא נצפה בסרטון.","lead":"שני מציגים מציעים שתי זוויות למדידה בעידן הסוכנים. סיימון מתאר מחקר רחב מסטנפורד על כ-150 אלף מהנדסים, שבו פאנל מומחים (ומודל שלמד לחקות אותו) מעריך את הקוד, ומראה שהשימוש ב-AI פוגע בצוותים ובפרטים בצורה לא אחידה. רוב מציג בדיקה ממוקדת של skills: האם הסוכן עוקב אחרי הוראות, באילו קטגוריות skill עוזר, ואיך למדוד אותו. בסוף יש שבע שאלות קהל.","chapters":[{"title":"מה אינו חלק מההרצאה: פתיח המנחה","body":["לפני ההרצאה, המנחה מראה את ה-skill של granola שמכיל את ההקלטות של כל ההרצאות בכנס: ברישום של Tessl, תחת AI Native DevCon 2026 LDN, אפשר למצוא את ההרצאות שהשתתפתם בהן ולשאול עליהן שאלות. הוא מבקש משוב לצוות Tessl, מזכיר שהוסיפו מקומות לסדנאות אחר הצהריים ושמי שמקבל מקום צריך להגיע בזמן, אחרת מכניסים את רשימת ההמתנה.","אחר כך הוא מציג את הצמד ואת נושא ההרצאה כ\"מווייבס למדדים: איך באמת למדוד מה הסוכנים עושים\"."],"points":[],"kind":"idea"},{"title":"המטרה: להבין מה קורה בפועל, לא רק לספור","body":["הם מציעים שני מבטים. מלמעלה למטה: מחקר מתאם על הרבה מאוד מהנדסים. מקרוב: כמה פעמים skill אחד עוזר למודל אחד להשלים משימה אחת. הטענה: צריך להבין מה מאחורי הנתונים ואיך לשפר, לא רק לראות אם \"זה נראה נכון\". התמלול בפתיחה מעורער מאוד ולא מאפשר לשחזר את כל המסגור."],"points":[],"kind":"idea"},{"title":"המחקר של סטנפורד: גודל ושיטה","body":["סיימון אומר שהוא חוקר בקבוצת SEPR בסטנפורד. לדבריו זה המחקר הגדול ביותר של פריון הנדסת תוכנה, עם כ-150 אלף מהנדסים שנרשמו בצורה כלשהי. החברות מתחייבות לתקופה של שנה, והחוקרים מסתכלים על כל מאגר הקוד, כל המהנדסים וכל שפות התכנות, ומחפשים דפוסי התנהגות. הוא מזכיר שחלק מהממצאים התפרסמו בכלי תקשורת. (הנתון על \"כ-10% מהמהנדסים\" שחוזר בתמלול לא ברור ולא נכלל.)","הבעיה: ספירת commits או שורות קוד אינה מדד טוב. מה שעבד להם: מומחים קוראים את הקוד ועונים על שאלות, למשל כמה זמן לדעתם לקח לממש, כמה זמן ייקח להם עצמם, ושאלות על תחזוקתיות וגמישות. הפתעה: בפאנל ובין שופטים ההסכמה גבוהה (\"שזה הפתעה כי בפגישות הנדסה אנשים לא מסכימים על דבר\"). לכן אימנו מודל למידת מכונה שמנסה לחקות את פאנל המומחים, ובעזרתו מריצים את הניתוח בקנה מידה."],"points":[],"kind":"idea"},{"title":"מה הם רואים: צוותים ויחידים","body":["הם בדקו 46 צוותים לאורך תקופה (המספר 46 מופיע בתמלול, אך תקופת הזמן והמתודולוגיה המדויקת לא ברורים: ציינו שהם נאלצו להתאים את המתודולוגיה באמצע). בהתחלה לא היה הבדל גדול בין צוותים שהשתמשו ב-AI לאלה שלא. עם הזמן ההפרש גדל: סיימון אומר שהוא מגיע עד כ-60% הבדל ביולי 2026 לעומת \"כ-5%\" שנה קודם (התאריכים והמספרים מוטעים בתמלול, ולכן מסומנים כלא מאומתים).","ברמת הצוות, ההבדלים עצומים. מי שמפגר לא רואה שינוי משמעותי בתפוקה, ובמצטיינים ההבדל גדול. ברמת היחיד יש הבדל \"הגדול ביותר שראינו\" במחקר שהחל ב-2020. סיימון אומר שעבד בעבר בעמק הסיליקון והאמין שמהנדס \"פי 10\" הוא מיתוס, אבל עכשיו הוא רואה סימנים: אנשים שיודעים ליצור סוכנים ולעבוד איתם מגיעים לתוצאות טובות משמעותית."],"points":[],"kind":"idea"},{"title":"שינוי בדירוג: מי עולה ומי יורד","body":["הם בדקו עד כמה מי שהיה בצמרת נשאר שם: מתאם הדירוג היה לפי דבריו כ-0.70 ואז ירד ל-0.45 (הנתונים נשמעים כך בתמלול, בלי ודאות לגבי ההגדרה). המשמעות לפי סיימון: הדרכים שהביאו אנשים לצמרת כבר לא מספיקות. הוא מציע השערה (ולא ממצא): אנשים שהיו עסוקים בעזרה לאחרים ועכשיו, עם אוטומציה, יש להם זמן ו\"הורגים את זה\", ומנגד אלה שהיו בצמרת יורדים."],"points":[],"kind":"idea"},{"title":"רמות הרתמה והמאמר","body":["בהמשך הם בוחנים איך אנשים מתזמרים סוכנים. סיימון מציין מאמר שהוגש לכנס IEEE Automated Software Engineering (כפי שהוא נשמע, \"ace\"). הם מנתחים ארטיפקטים ב-repos, מחשבים embeddings, משייכים רמות ומשווים אותן למדד התפוקה. בקצרה: ללא תשתית (הוראות, skills, כלים) ה-AI לא מקדם הרבה ויש יותר שינוי בנפח הקוד. ברמה 2 יש עלייה משמעותית בתפוקה וירידה בפגמים. ברמות 2-3 כל המדדים שנבדקו משתפרים, וזה לא היה כך בהתחלה, כשהטיעון היה ש-AI רק מכניס פגמים. הגדרת הרמות המלאה לא ברורה בתמלול."],"points":[],"kind":"idea"},{"title":"רוב: איך בודקים skill","body":["רוב מציג בדיקה ממוקדת של skills: הוא אומר שיש להם 500 skills ו-1000 משימות, ו\"19 שילובים\" של מודלים והגדרות (המספרים נשמעים כך אך לא מאומתים). המשימות סינתטיות אך מבוססות על מה שה-skill אמור להפעיל, למשל לאבטח API או להחליף אימות מסיסמה למנגנון אחר. זה לא \"לדחוף גבולות\" אלא כמו משימות מוגדרות היטב שמצפים ממהנדס לבצע.","הממצא על קיום הוראות: הוא מדבר על קפיצה גדולה בעקיבה אחר ההוראות כשה-skill קיים (המספר המדויק מבולבל בתמלול ולא נכלל). נתון מעניין: ב-55% מהמקרים המודל עוקב אחר ההוראות גם כשה-skill לא קיים, כי המידע כבר נמצא במשקולות. רוב מסיק שזה חשוב: אל תשרפו טוקנים על מידע שהמודל כבר יודע."],"points":[],"kind":"idea"},{"title":"איפה skills מועילים ואיפה לא","body":["רוב מציג שלוש קטגוריות שחוזרות בהן skill משנה: (1) הנחיות ארגוניות או קונבנציות מקומיות, למשל אילו ספריות מותר להשתמש. (2) קונפיגורציה ותלויות שחייבות להיות מוכנות לפני פריסה, כמו הגדרת credentials של API. (3) דפוסים אסורים או מיושנים, למשל לא ליצור משהו חשוף לאינטרנט אלא אם חייבים.","דוגמה: סוכן מתבקש לממש משהו, ובקוד קיים נעשה שימוש בדרך ישנה כי היא מופיעה בנתוני האימון. הקוד יעבור את הבדיקות אבל יהיה יקר או לא עדכני. הידע על דרך חדשה (נניח API שהשתנה לאחרונה) ייכנס למודלים רק חצי שנה מאוחר יותר, ולכן skill שמעדכן הוא תיקון בינתיים. הדוגמה הקונקרטית עם הטוקנים בתמלול לא ברורה.","הקטגוריות עם השיפור הגדול: היכן שרוצים משהו שונה מהמצב הרגיל או שיש מעט ידע קודם בנתוני האימון, כמו קונבנציות של ארגון, אבטחה ותאימות. בקטגוריות כמו עיבוד נתונים כללי ההבדל קטן כי יש מעט דרכים לעשות. גם בבדיקות (testing) יש ממצא מעניין שהתמלול לא מאפשר לשחזר. המסקנה: להשקיע במבנה היכן שהקונבנציות מקומיות וחשובות לעסק."],"points":[],"kind":"idea"},{"title":"מה למדוד","body":["רוב טוען שלא מספיק לבדוק רק את התוצאה הסופית. צריך למדוד לאורך כמה ממדים: האם ה-skill בכלל מתגלה (discovery: התיאור שלו תופס על פי דבריו תקציב קבוע ברירת מחדל, מספר לא ברור בתמלול, ולכן צריך לבדוק ולשפר את התיאור), האם המסלול (trajectory) עוקב אחר הזרימה המכוונת, ולבסוף האם הקוד עובר את הבדיקות. נקודה חשובה: שינוי ה-harness סביב המודל יכול להזיז ציונים בצורה גדולה (הוא אמר \"200%\", ללא הקשר ברור), כי המודלים אומנו על מערכות מסוימות. לכן לא מספיק לבדוק מודל, צריך לבדוק את כל המערכת."],"points":[],"kind":"idea"},{"title":"מקורות ומה הלאה","body":["סיימון אומר שהניתוח הוא קוד פתוח ונמצא באתר שלהם. המימד שחסר להם הוא הקשר בין output לבין outcome, וגם יש אי ודאות לגבי כמות ההוצאה (הוא מתכוון להוצאה על טוקנים). לכן הם הקימו קבוצת משתתפים שבה ארגונים יכולים להירשם ולשתף נתונים. הם עובדים גם על שאלה איך לבחור ולנצל טוקנים בצורה הטובה ביותר."],"points":[],"kind":"idea"},{"title":"האם נכללו בקבוצות נתוני גיל?","body":"סיימון: לא נאסף גיל, בין היתר בגלל רגולציה ואפשרות הסרה, אבל יש נתוני תפקיד ואזור, ומסיקים משהו מהתפקיד. בחברות שחלקן נותחו, חלק מהמהנדסים עובדים עשר שנים ויותר. המנחה מוסיף הערה שבכנס הזה התפלגות הגילאים נוטה לבכירים, והוא תוהה אם אלה בכירים שחוזרים מניהול למעשה.","kind":"qa"},{"title":"האם עובדים שמדורגים נמוך כי אינם משתמשים ב-AI מוטים את הסטטיסטיקה?","body":"המציגים: לא. מנתחים רק פלט (פאנל מומחים וניתוח אלגוריתמי), לא בודקים אם נעשה שימוש ב-AI.","kind":"qa"},{"title":"האם מפרסמים נתונים על ה-harness שבו המודל רץ?","body":"בעקבות הבהרה, הם אומרים שה-harness והוראות ברורות משנים, ושבכוונתם לשתף את המספרים באופן רחב וקבוע, לא רק במאמר אחד.","kind":"qa"},{"title":"איזו איכות קוד יש בקונבנציות שמשפיעות על התוצאה?","body":"רוב: הם בדקו עקיבה אחר הוראות ולא איכות קוד. איכות היא סובייקטיבית. יש ניתוח פאנל נפרד על תחזוקתיות וחלק מעבודה בהכנה עם כלי APM, אך לא נאמרו ממצאים.","kind":"qa"},{"title":"כמה זמן לוקח לאנשים להגיע למצב של ביצועי שיא ומה מפעיל זאת?","body":"סיימון: עוד לא בדקו את הדינמיקה. מי שמסווג כמצטיין AI נוטה להישאר שם, ונראה שזו תפיסת עולם. אין ממצא על הטריגרים. בהמשך נמסר שהמשתתפים יכולים להשתמש בפאנל. התשובה האחרונה מבולבלת בתמלול.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["ההשפעה של AI על צוותים לא אחידה: לפי סיימון, צוותים עם תשתית ו-skills משפרים תפוקה ללא עלייה בפגמים.","skills נותנים ערך בעיקר היכן שהידע בנתוני האימון חלש או שהקונבנציה מקומית.","לפי רוב, המודל כבר עוקב אחרי חלק מההוראות לבד, ולכן אין טעם לחזור עליהן ב-skill.","מודדים גילוי, מסלול ותוצאה, ובודקים את המערכת כולה (מודל ו-harness)."],"kind":"idea"}],"diagram":{"title":"שני מבטים על מדידה: מקרו (צוותים) ומיקרו (skill)","type":"flow","nodes":[{"id":"repo","label":"קוד ה-repository","note":"כל המהנדסים והשפות"},{"id":"panel","label":"פאנל מומחים","note":"ציון זמן, תחזוקתיות, גמישות"},{"id":"model","label":"מודל שמחקה את הפאנל","note":"מאפשר ניתוח בקנה מידה"},{"id":"macro","label":"מקרו: צוותים ויחידים","note":"הבדלי תפוקה, רמות רתמה"},{"id":"task","label":"משימה סינתטית","note":"מכוונת ל-skill"},{"id":"skill","label":"skill","note":"קונבנציות, קונפיגורציה, דפוסים אסורים"},{"id":"metrics","label":"שלושה מדדים","note":"גילוי, מסלול, מעבר בדיקות"}],"edges":[{"from":"repo","to":"panel","label":"נבדק"},{"from":"panel","to":"model","label":"מאומן ללמד"},{"from":"model","to":"macro","label":"מריץ בקנה מידה"},{"from":"task","to":"skill","label":"אמור להפעיל"},{"from":"skill","to":"metrics","label":"נמדד"}]},"terms":[{"term":"Eval","en":"Evaluation","definition":"בדיקה שיטתית של התנהגות סוכן או מודל מול משימות ומדדים, במקום להסתמך על תחושה (vibes)."},{"term":"פאנל מומחים","en":"Expert panel","definition":"אנשי מקצוע שמעריכים קוד לפי שאלות קבועות. לפי סיימון ההסכמה ביניהם גבוהה, ומודל אומן לחקות אותם."},{"term":"Skill","en":"Skill","definition":"אוסף הוראות שנטען לסוכן כדי להנחות עבודה ספציפית, למשל קונבנציות ארגוניות."},{"term":"Harness","en":"Harness","definition":"המעטפת שמריצה את המודל (כלים, הוראות, תהליך). לפי רוב היא משנה מאוד את התוצאות."},{"term":"Trajectory","en":"Trajectory","definition":"רצף הצעדים שהסוכן עשה, לא רק התוצאה הסופית."}],"gaps":["התמלול נגמר כשהמנחה מכריז על הפסקה. התשובה לשאלה האחרונה מבולבלת וחלקים ממנה לא ברורים.","התמלול הוא ASR מעוות מאוד. מספרים (10%, 46 צוותים, 60%, 0.70 ו-0.45, 500 ו-1000 ו-19, 55%, 1.2% וה-200%) הם כפי שנשמעו ולא אומתו, וחלקם הושמטו.","הכותרת מהמארח (\"מווייבס למדדים\") שונה מהכותרת ברשימת ההשמעה.","שמות המציגים והתפקיד של רוב לא אומתו מעבר להצגה על הבמה.","לא נמצאה גרסה רשמית להשוואה."],"source_refs":["https://www.youtube.com/watch?v=4d3-Zrmf9Wo"]},{"number":42,"id":"BV7RYioryKE","url":"https://www.youtube.com/watch?v=BV7RYioryKE","type":"session","type_he":"סשן","duration":"30:23 דקות","title_he":"WebMCP: אפליקציות ווב מהירות וזולות יותר לסוכנים","speaker_he":"מקסימיליאנו פירטמן","summary":"מקס מסביר ש-WebMCP הוא ממשק מוצע שבו אתר חושף לסוכן כלים (שם, תיאור, סכמת קלט ופונקציית ביצוע) במקום שהסוכן ינחש לפי פיקסלים, DOM וצילומי מסך. הוא משווה אותו ל-MCP הרגיל, מראה הדגמה עם אפליקציית מונדיאל ועם Doom, ונותן עקרונות לעיצוב כלים והמלצה איך להתחיל.","takeaways":["WebMCP הוא ניסיוני.","כלי אחד למטרה אחת.","רישום כלים לפי מצב העמוד.","שגיאות ברורות ופלט קטן."],"category":"כלים ופרוטוקולים","coverage":"תמלול מלא עד 'two seconds left', ללא שאלות ותשובות.","source_basis":"תמלול מלא של הרצאה (כ-4,000 מילים) מקובץ המקור, בהשוואה לטקסט הרשמי talk-firtman-web-mcp-agentic-web (שניהם מעוותי ASR במקומות שונים). בלי חלק שאלות וללא חלק קהל. לא נצפה בסרטון.","lead":"מקס מסביר ש-WebMCP הוא ממשק מוצע שבו אתר חושף לסוכן כלים (שם, תיאור, סכמת קלט ופונקציית ביצוע) במקום שהסוכן ינחש לפי פיקסלים, DOM וצילומי מסך. הוא משווה אותו ל-MCP הרגיל, מראה הדגמה עם אפליקציית מונדיאל ועם Doom, ונותן עקרונות לעיצוב כלים והמלצה איך להתחיל.","chapters":[{"title":"הפתיחה והרקע: הסוכנים והווב","body":["מקס מציג את עצמו ואומר שהוא כותב ספר חדש על \"ווב וניל\" (בלי ספריות ומסגרות) שמיועד גם לסוכנים, כי פחות תלויות הן גם יותר מאובטחות וגם טובות יותר להקשר. הוא אומר שאנחנו בימים מוקדמים של מה שנקרא \"הווב הסוכני\".","הוא מפרט שלושה כיוונים: סוכנים רוצים לבנות לווב (כשמבקשים אפליקציה, התוצאה כמעט תמיד web app). הווב רוצה להריץ סוכנים (סוכן בתוך האתר ב-JavaScript, או אפליקציות MCP שרצות בתוך Claude או ChatGPT כמיני־אפליקציה). משתמשים גם גולשים באמצעות סוכנים, למשל Gemini ב-Chrome, וסוכנים גולשים בעצמם. ההרצאה מתמקדת בפתרון שיעזור למפתחי ווב לשפר את יכולת הסוכנים לעבוד עם האתר."],"points":[],"kind":"idea"},{"title":"הבעיה: איך סוכנים גולשים היום","body":["הדוגמה: אתר לעקוב אחרי מונדיאל FIFA, עם חיפוש משחקים, מעקב אחרי נבחרת ובורר תאריכים. אם מבקשים מסוכן (open claw, Codex, Claude Code) לבדוק מידע, ייקח זמן להבין את הממשק, וגם הרבה הקשר וכסף על טוקנים. לגלות את שמינית הגמר, חצי הגמר והגמר יכול לקחת כמה דקות.","הטכניקות כיום: (1) connector: שרת MCP או CLI שחברת האתר צריכה לממש. (2) בקשת HTTP פשוטה (כמו curl): לא מריצה JavaScript, ולכן באפליקציית עמוד יחיד לא מקבלים נתונים אמיתיים. (3) שימוש בדפדפן: תוסף ל-Chrome או דפדפן פנימי (ל-Codex יש דפדפן פנימי), שקורא DOM, עץ נגישות וצילומי מסך. (4) computer use: עכבר ומקלדת וצילומי מסך של כל המחשב, למשל כשרוצים לבדוק רינדור ב-Safari.","הבעיה המרכזית: זה ניחוש. הסוכן מסתכל בצילום מסך או ב-DOM, מסיק שצריך ללחוץ על אייקון לוח השנה, מצלם שוב, בודק מה השתנה, וחוזר חלילה. זה שורף טוקנים, זמן וחלון הקשר."],"points":[],"kind":"idea"},{"title":"הרעיון של WebMCP: חוזה במקום ניחוש","body":["WebMCP נותן ל-front end לחשוף יכולות ולא רק פיקסלים. במקום להסיק מפיקסלים, selectors וניסיונות חוזרים (עם מודלים רב־מודליים יקרים), עוברים מהסקה לחוזה שמפתח האתר מגדיר: כלי עם שם, תיאור, סכמת JSON ופונקציית ביצוע (execute), בדרך כלל פונקציית JavaScript שהסוכן מפעיל.","הוא מדגיש שהוא לא מציג את זה כפתרון לכל הבעיות, אלא לחלק מהן."],"points":[],"kind":"idea"},{"title":"למה לא מספיק MCP רגיל","body":["MCP הרגיל מחבר סוכן ישירות ל-back end: שרתים, API, נתונים ותהליכים. יש לו אתגרי אימות באתרים מסוימים, והוא לא רואה את מה שחי בצד הלקוח: localStorage ו-IndexedDB, מערכת קבצים של המשתמש, חיישנים (הוא נותן דוגמה של web apps למשקפי Meta Display שבהם הסוכן עשוי להזדקק לנתוני חיישן שלא יגיעו מהשרת).","WebMCP מדבר עם ה-front end: העמוד הנוכחי, מיקום הגלילה, נתוני טופס שהוקלדו, מצב ה-UI, כל סשן המשתמש, והתקנים כמו web serial. לכן זה לא אחד או השני אלא שניהם, לפי הצורך. מקס מדגיש ש-WebMCP בהשראת MCP אך אינו יורש ממנו: הפרוטוקול אחר. הוא מצטט ציוץ (בלי שם) שאומר ש-WebMCP ל-MCP הוא כמו JavaScript ל-Java."],"points":[],"kind":"idea"},{"title":"סטטוס ויישום","body":["זה API מוצע לתקן, עדיין לא המלצת W3C אך בדרך לשם. מחבר האתר מספק כלים להקשר של סוכני AI (גם צ׳אטבוט, אך זה מתאים יותר לסוכנים). לפי מקס, מחר (היום שאחרי ההרצאה) יצא Chrome 149 ויהיה origin trial, כלומר אפשר להשתמש עם משתמשים אמיתיים. אחרת צריך להפעיל flag. סוכנים חוזרים לטכניקות אחרות אם לאתר אין כלים. צריך ליישם את זה, זה לא מופיע אוטומטית.","לגבי סוכני קוד: זה לא מחליף בדיקות. בדיקות מדמות משתמש, וכעת אפשר גם לבדוק את הכלים ביחידות, כך שיש יותר בדיקות. אבל זה הופך שימוש בכלים באפליקציה למהיר וזול יותר, ומאפשר לסוכן למלא טפסים בלי לנחש מה למלא ואיפה. אפשר גם ליצור כלי לוג ודיבאג שאוספים נתונים מה-front end לערכת הבדיקות, למשל רשימת השגיאות בסשן או אבחון עם כל הקשר הדפדפן."],"points":[],"kind":"idea"},{"title":"מבנה של כלי","body":["כלי הוא אובייקט עם שם תיאורי, תיאור, סכמת קלט (הפרמטרים שהכלי צריך מהסוכן) ופונקציית execute שנקראת כשהסוכן מחליט להפעיל אותו. את התיאור יש לכתוב לסוכנים ולא לבני אדם: \"הלקוח שלנו הוא סוכן AI\". הסוכן, כמו ב-MCP, שואל את הדפדפן או את האפליקציה אילו כלים זמינים, ובוחר לפי המטרה.","בכלי הפיתוח של Chrome יש inspector. הדוגמה הסטנדרטית של צוות Chrome היא חיפוש טיסה או מלון: במקום למלא טופס, קוראים לכלי."],"points":[],"kind":"idea"},{"title":"ההדגמה עם אתר המונדיאל","body":["באתר של מקס יש כלים כמו get matches by date, team matches, list teams, groups ו-search matches. הוא שואל איזו משחק שני של אנגליה, והסוכן עונה לפי הרצת כלי. אחר כך: האם אפשר גמר בין ארגנטינה לאנגליה? הסוכן קורא כמה כלים עם ארגומנטים שונים ועונה שכן, אחת צריכה לנצח בבית והשנייה להיות סגנית, אחרת ייפגשו בחצי הגמר. הוא שואל גם מי תזכה בגביע, ומתבדח שהוא מארגנטינה ורוצה לחזור הביתה בשלום. המודל בדפדפן בדמו הוא Gemini."],"points":[],"kind":"idea"},{"title":"שני סוגי API: imperative ו-declarative","body":["Imperative: קוראים ל-API של המסמך (document model context, registerTool, כפי שנשמע) ומעבירים את האובייקט עם פונקציית execute. אפשר לרשום כמה כלים, ולא חייבים בטעינת העמוד: לפי מצב האפליקציה אפשר להוסיף ולהסיר כלים. execute מצפה ל-promise ולכן כל פעולה אסינכרונית עובדת, כולל קריאה ל-back end או התקן Bluetooth.","Declarative: טופס HTML עם שם ותיאור של הכלי (שניהם חובה). יש גם מאפיין boolean של auto submit, שבו המפתח מביע שהוא מסכים שהסוכן ישלח את הטופס אוטומטית. בשדות input, textarea, select ורכיבי טופס אפשר להוסיף תיאור פרמטר, אם התווית לא מספיקה (אופציונלי). הסוכן רואה למשל כלי create ticket עם הארגומנטים."],"points":[],"kind":"idea"},{"title":"הדגמת Doom: האם זה עובד באמת?","body":["מקס הוסיף WebMCP למנוע Doom בקוד פתוח עם כלי תנועה וכלי מידע (צילום מסך ב-base64 והמיקום במפה, וערך boolean אם הסוכן פונה לקיר). הוא מבקש מהסוכן להתקדם 10 שניות, לסובב ולנוע בו־זמנית (הסוכן יכול להריץ כמה כלים יחד), ואז \"play Doom as a maniac for one minute\" והסוכן משחק. הנקודה: אפשר לעשות כמעט כל דבר דרך כלים."],"points":[],"kind":"idea"},{"title":"איך משתמשים בזה היום","body":["בכלים כמו Claude Code, Cursor או Codex עדיין אין תמיכה ישירה. הגשר הנוכחי: Chrome DevTools MCP, שהוא כלי MCP שמפעיל Chrome ואיתו מריצים WebMCP. סוכן הקוד מתחבר ל-DevTools MCP, שיוצר מופע Chrome חי, מפעיל את האתר, מפרט את הכלים ומריץ אותם. ב-headless זה לא עובד כרגע כי זה מתאים להקשר אמיתי (עשוי להשתנות). אפשר גם דרך Puppeteer בדגל ניסיוני. מקס מצפה שבעתיד ה-browser tools של הסוכנים יתמכו ישירות (למשל Codex, ChatGPT עם אפליקציות MCP, או תוסף דפדפן ל-open claw), אך זה עדיין ניסיוני."],"points":[],"kind":"idea"},{"title":"עקרונות עיצוב לכלים","body":["עיצוב כלים הוא עיצוב API, אבל הצרכן הוא המודל. הנחיות: מטרה אחת לכל כלי ובלי חפיפה כדי שהסוכן יבחר נכון. להיות מודעים למצב ולרשום רק כשהכלי שימושי (משתמש מחובר או לא מחובר, למשל). שפה פשוטה שמתארת מה קורה. החזרת שגיאות משמעותיות וטכניות כדי שהסוכן יתקן בלי אדם. החזרת פלט קטן שמכיל בדיוק מה שהתבקש."],"points":[],"kind":"idea"},{"title":"סטטוס ניסיוני והמלצה להתחיל","body":["זה מבטיח אבל ניסיוני: יש דיונים רבים על מה להוסיף או להסיר מהמפרט, זה מאחורי דגל ב-Chrome, ומחר origin trial שבו ממלאים טופס עם ה-origin של האתר. ה-API הסופי עשוי להשתנות בעוד כמה חודשים. זה זמן טוב ללמוד ולהצטרף לדיון.","ההמלצה: לבחור עמוד או מצב אחד בעל ערך גבוה באפליקציה ולחשוף ממנו כלי אבחון בלבד (בטקסט הרשמי: read-only), להעריך אותו עם קריאות וארגומנטים מ-Claude Code, Cursor או Codex, ולאוטמט עם DevTools MCP או Puppeteer. בסוף אפשר לשאול למשל \"למה העמוד הזה נכשל ב-QA?\" והכלי יריץ אבחון."],"points":[],"kind":"idea"},{"title":"סיכום","body":["WebMCP יכול להפוך אפליקציות ווב למהירות וזולות יותר לסוכני קוד. זה API ניסיוני. הוא חושף כלים מה-front end ולא מה-back end, וזה ההבדל מ-MCP. הוא משתמש בהקשר המלא של הדפדפן וניתן להשתמש בו עכשיו ב-origin trial ב-Chrome או דרך Chrome DevTools MCP או Puppeteer."],"points":[],"kind":"idea"},{"title":"מה נשאר מהסשן","body":[],"points":["סוכנים יכולים לדלג על ניחוש בעזרת חוזה מפורש של כלים.","WebMCP ו-MCP משלימים זה את זה: back end מול front end.","הכלי נכתב עבור מודל: מטרה אחת, שפה פשוטה, שגיאות טכניות ופלט קטן.","המצב ניסיוני, ויש להתחיל מכלי אבחון אחד."],"kind":"idea"}],"diagram":{"title":"WebMCP מול MCP: שני ערוצי גישה של סוכן","type":"flow","nodes":[{"id":"agent","label":"סוכן","note":"מתכנן ובוחר כלים"},{"id":"mcp","label":"MCP","note":"ל-back end: שרתים, API, נתונים"},{"id":"webmcp","label":"WebMCP","note":"ל-front end: עמוד, מצב UI, אחסון מקומי, התקנים"},{"id":"tool","label":"כלי","note":"שם, תיאור, סכמת קלט, execute"},{"id":"fallback","label":"גיבוי","note":"צילום מסך, DOM, computer use"},{"id":"bridge","label":"גשר היום","note":"Chrome DevTools MCP או Puppeteer"}],"edges":[{"from":"agent","to":"mcp","label":"שרת"},{"from":"agent","to":"webmcp","label":"דפדפן"},{"from":"webmcp","to":"tool","label":"חושף"},{"from":"agent","to":"fallback","label":"אם אין כלים"},{"from":"bridge","to":"webmcp","label":"מחבר סוכן קוד"}]},"terms":[{"term":"WebMCP","en":"WebMCP","definition":"API מוצע לתקן שבו אתר חושף כלים לסוכנים מה-front end. לפי מקס, בהשראת MCP אך לא אותו פרוטוקול."},{"term":"Origin trial","en":"Origin trial","definition":"ניסוי של Chrome שבו אתר נרשם ומפעיל תכונה ניסיונית עם משתמשים אמיתיים."},{"term":"Imperative API","en":"Imperative API","definition":"רישום כלים בקוד JavaScript."},{"term":"Declarative API","en":"Declarative API","definition":"הגדרת כלי דרך טופס HTML עם מאפיינים."},{"term":"Chrome DevTools MCP","en":"Chrome DevTools MCP","definition":"שרת MCP שמפעיל Chrome חי, ושמשמש היום כגשר בין סוכן קוד ל-WebMCP."}],"gaps":["ההרצאה נגמרת בתודה (\"שתי שניות שנותרו\"). בטקסט הרשמי המנחה מסיים בהודעה על חזרה בעוד חצי שעה. אין חלק שאלות.","הנתונים על Chrome 149 ועל origin trial \"מחר\" הם כפי שנאמרו על הבמה ולא נבדקו.","שמות ה-API המדויקים (document model context, registerTool) נשמעים כך בתמלול ולא אומתו.","השמות Codex ו-open claw וה-Gemini כפי שנאמרו.","בטקסט הרשמי ובמקור יש הבדלי ASR קלים. אין סתירה מהותית."],"source_refs":["https://www.youtube.com/watch?v=BV7RYioryKE","https://github.com/AINativeDev/aidevcon-2026-ldn"]},{"number":43,"id":"7Sy2gSoxu7o","url":"https://www.youtube.com/watch?v=7Sy2gSoxu7o","type":"session","type_he":"סשן","duration":"29:01 דקות","title_he":"סוכנים על הקנבס עם tldraw","speaker_he":"סטיב רואיז · tldraw","summary":"סטיב מציג סדרת הדגמות של ניסויי AI שבנו ב-tldraw לאורך שלוש שנים: Make Real (ציור הופך לאפליקציה), מחשב tldraw (זרימות מבוססות גרף), סוכן בסרגל הצד, fairies (סוכנים שחיים על הקנבס ועובדים כצוות), ולבסוף אפליקציית שולחן עבודה שנותנת לסוכן גישה ישירה ל-API של העורך.","takeaways":["הערות וציור הם קלט יעיל למודלים.","אפשר לתת לסוכנים לעבוד על קנבס משותף.","code mode: להשתמש ב-API של העורך."],"category":"כלים ופרוטוקולים","coverage":"שוחזר מכתוביות (עד כ-1737 שניות), כולל שאלות ותשובות קצר.","source_basis":"כתוביות מלאות עם חותמות זמן (כ-4,500 מילים) שהושגו מחדש, כולל הפתיחה והסיום שחסרים בטקסט הרשמי talk-maple-tldraw-ai-canvas-experiments (הוא מתחיל באמצע משפט, מעוות ובלי תוויות דוברים). אין הבדל מהותי בתוכן. הרצאה בעיקר הדגמות חיות. לא נצפה בסרטון, ולכן תיאורי ההדגמות מבוססים על דברי הדובר בלבד.","lead":"סטיב מציג סדרת הדגמות של ניסויי AI שבנו ב-tldraw לאורך שלוש שנים: Make Real (ציור הופך לאפליקציה), מחשב tldraw (זרימות מבוססות גרף), סוכן בסרגל הצד, fairies (סוכנים שחיים על הקנבס ועובדים כצוות), ולבסוף אפליקציית שולחן עבודה שנותנת לסוכן גישה ישירה ל-API של העורך.","chapters":[{"title":"מה זה tldraw ולמה זה אחרת","body":["סטיב אומר שזו ההרצאה לפני ארוחת הצהריים, ולכן ירבה בהדגמות. הוא מציג את tldraw כלוח לבן שיתופי מקוון בסגנון Miro או Excalidraw, ומציין שני הבדלים: \"הוא טוב מאוד\", והוא אתר רגיל שבו כל מה שעל הקנבס הוא אפליקציית React אחת. אין אלמנט canvas אלא div-ים ו-SVG. זה יהיה חשוב בהמשך.","tldraw הוא גם SDK, וכך החברה מרוויחה: חברות שרוצות קנבס במוצר מקבלות רישיון ולא בונות הכול מאפס, כמו שלא בונים עורך טקסט. הוא מציין כלקוחות את הקנבס החדש של Replit ואת Luma AI, ואומר שאם רואים מוצר קנבס מגניב ב-2026, \"כנראה זה נבנה עלינו\".","חלק מעבודתו כמי שמוכר SDK הוא לבנות דברים מגניבים איתו, ובשנים האחרונות רבים מהם כוללים AI. הוא מראה שהתוכן על הקנבס הוא תוכן ווב רגיל, למשל סרטון YouTube שאפשר להפעיל, כמו שב-Notion עורך מסמכים הוא גם HTML ו-CSS רגילים."],"points":[],"kind":"idea"},{"title":"Make Real (נובמבר 2023): ציור הופך לאפליקציה","body":["בנובמבר 2023 הושק GPT-4 with Vision. לדבריו זו הפעם הראשונה שמודל ראייה טוב זמין דרך API למפתחים, בתצוגה מקדימה עם כ-30 בקשות ביום, ויקר להפליא. הציוץ על Make Real, אומר סטיב, היה מהראשונים של \"AI שמייצר קוד\" שיצא מקהילת ה-ML הצרה לקהל רחב. הוא מזכיר שאז לא היה המונח vibe coding ולא Lovable.","הרעיון: קנבס שבו מציירים דיאגרמות וסקיצות, ו-AI שרואה אותן ויוצר את מה שצויר. הוא מדגים תחילה בטקסט בלבד (טיימר כתום עם כפתורי start, stop ו-add time). אחר כך אפשר לקבל תוצאה דומה מציור בלבד, כאילו צילמו מסך והדביקו ל-Cursor.","התגלית שהוא מדגיש: אפשר לצייר מעל האתר שנוצר ולערוך בהערות. כשהוא מצייר \"green\" ושולח שוב, התמונה כולה (כולל האתר) נשלחת למודל. החלפת מיקום הכפתורים לא הצליחה, אבל הצבע הצליח. \"ההערה (annotation) יכולה להיות קלט למודלי שפה\". סטיב אומר שלקוחות ה-SDK, כולל גוגל (הוא מזכיר Stitch ושמות נוספים שנשמעים בתמלול כ\"mix borders\"), Replit, Luma ו-Runway, לקחו את הרעיון הרחק.","הדגמה מורכבת: ציור של אפליקציית מצלמה עם מתגי dot matrix וצבעים, בקרת גודל נקודה ופאנל תמונות ממוזערות. לתאר את זה בשפה יהיה מסובך. הוא עובד עם מודל Gemini (נשמע \"Gemini 3 flash preview\") ואז מחליף למודל חזק יותר. המשתמש מביא את הטוקן שלו (BYO token), ו-tldraw עוד לא מרוויחה מזה. התוצאה עובדת, כולל מצלמה, צבע, dot matrix, גודל נקודה וצילום. כל זה מתמונה כקלט."],"points":[],"kind":"idea"},{"title":"מחשב tldraw: גרף במקום צ׳אט","body":["עוד ניסוי מוקדם היה \"tldraw computer\" שמשתמש בקנבס לדברים שצ׳אט לא מתאים להם: הסתעפות שיחות ופרומפטים מרובי שלבים שחוזרים על עצמם. בצ׳אט זה קשה, בקוד או בעורכי workflow קל, אך קשה להיות יצירתי. בקנבס אפשר לבנות גרפים מכוונים ולבנות הקשר באופן דינמי.","הדגמה בהשתתפות הקהל: הם בוחרים ספורט (real tennis), מטבח (מלזי) ודגל. כל קופסה היא פרומפט קטן עם מבנה חוזר ומריץ סקריפט משלו לפי הקלטים שמצביעים אליו: כתיבת כתבה על משחק אליפות על בסיס חוקי המשחק, ושרטוט של סמל תלת־ממדי. התוצאה כוללת כתבה על \"Leopards Roar to Victory in inaugural Rimba Cross Tennis Championship\" (כפי שנשמע, שם הגביע והקבוצה כפי שנשמעו בתמלול), וחוקים שנראים מורכבים מהצפוי. הסמל התלת־ממדי לא נוצר נכון. כדי לערבב מחדש מספיק לשנות קלט ולהריץ שוב."],"points":[],"kind":"idea"},{"title":"2024 והלאה: מה אנחנו רוצים מהקנבס","body":["מ-2024 הם שאלו מה רוצים באמת מהקנבס. סטיב אומר שתכונת הקילר של קנבס היא שיתוף פעולה: 8 עד 15 אנשים באותו מסמך עם סמנים שעפים. אז למה לא גם AI? כך יצאו למסע ארוך: ללמד AI לראות את הקנבס, להבין אותו וגם לפעול עליו, כמו שהוא עצמו יוצר ומשנה צורות."],"points":[],"kind":"idea"},{"title":"הסוכן בסרגל הצד (2025)","body":["הם \"העתיקו בדיוק\" את סרגל הצד של Cursor כפי שהיה ב-2025. זה לולאת סוכן מלאה: מסתכל, יוצר על הקנבס, עושה review, ואפשר לקבל או לדחות. בדוגמה הוא מצייר חתול עם אוזניים ומבקש מהסוכן לסיים אותו. אחר כך מצייר שולחן ומבקש שהחתול יעלה עליו. מה שהסוכן יצר אינו תמונה אלא אותם צורות שגם משתמש יוצר, כלומר מדברים באותה שפה על הקנבס.","הוא מודה שהמהלכים הגדולים (move) היו חלשים בהתחלה ושיפרו בגרסאות חדשות. הדגמה נוספת: הוספת מסכים לשרטוטי wireframe, שזה סוג התוכן שמודלי התמונה רגילים אליו (תמונות, תוכנה). סטיב אומר שה-harness לא טוב בהזזת חתולים אך טוב ביצירת UI על הקנבס."],"points":[],"kind":"idea"},{"title":"Fairies: סוכנים שחיים על הקנבס","body":["בעיה: הסוכן \"כלוא בסרגל הצד\", מופע יחיד. הפתרון: להביא אותו אל הקנבס כמו משתמשים אחרים. כך נולדו fairies: כל אחת מופע של אותו harness שחי על הקנבס. בהתחלה זו הייתה דרך לראות איפה הסוכנים, מי מי, ואפשר להגדיר אותם (כובע, אורך רגליים). אפשר להרים אותם ולזרוק אותם. מדברים איתם (\"make a move as X\"), ורואים את המצב שלהם: חושב, בודק או עובד.","הם פועלים במקביל ויודעים איפה האחרים. כשמסמנים שלוש ואומרים \"play a full game of tic-tac-toe\" הם פועלים כיחידה: אחת נבחרת למנהיגה ומנסחת תוכנית, הכנפיים משנות צבע כסימן לצוות, והמתאמת יוצרת רשימת משימות ומאצילה לשאר. אפשר לקרוא את \"צ׳אט ה-IRC\" שלהם. בהדגמה החיה הם שיחקו בצורה מבולגנת, ובסוף לא זיהו ניצחון וסטיב אומר בהומור \"Everyone wins\". הוא מציין שיש ל-reviewer כלים לעצור את הייצור ושהוא אמור לבדוק אם מישהו ניצח.","הם יכולים גם לבצע דברים מורכבים: להפוך PRD שלם ל-wireframes וליישר סידור. זה שיתופי: אפשר לשתף קישור. אפשר לנסות ב-fairies.tldraw.com (בתמלול נשמע \"fairies.tildraw.com\"), חינם, על חשבון הטוקנים של סטיב. התזמור הוא רק בתוך הפיות של משתמש אחד, אבל הם ניסו 10 אנשים ו-30 סוכנים באותו מסמך, וה-UI חייב לתת affordances לשיתוף פעולה בין אדם ל-AI וגם בין כמה אנשים ל-AI."],"points":[],"kind":"idea"},{"title":"אפליקציית שולחן עבודה ו\"code mode\"","body":["הניסוי החדש ביותר: אפליקציית desktop שנותנת חוויה דמוית MCP, כך שכל סוכן יכול לעבוד עם הקנבס. הדוגמה: \"הנה הקוד שלי, צור דיאגרמה של איך זה עובד\", ואז לשנות את הדיאגרמה ולבקש מהסוכן לעדכן את הקוד בהתאם. יש להם MCP app ל-Cursor ול-Claude, אבל הוא \"כלוא בתוך אפליקציה\". מהאפליקציות האהובות עליו הן אפליקציות desktop עם שרת MCP מקומי (הוא מזכיר Paper, Pencil ו-IDE רגיל).","אז הם הסתכלו על \"code mode\": במקום הרבה קריאות MCP, לתת לסוכן קוד להריץ. ל-tldraw יש API זמן ריצה (למשל editor.selectAll). מכיוון שהכול מקומי, הם נתנו ל-AI גישה ישירה לעורך, והוא \"עושה תכנות מטורף\" מעל הקנבס. שאלו אם אפשר להפוך אלמנטים לאינטראקטיביים: גובה עיגול ישפיע על דמות, כפתורים יעבדו. אין בקנבס פרימיטיב של \"כשלוחצים, תעשה\", אבל יש מספיק רמה נמוכה, ו-Claude בעצם מזריק סקריפטים לאפליקציה. הם נתנו לו \"פתח\" לעשות זאת.","דוגמה: \"קח את כל התמונות משולחן העבודה שלי, שים ב-tldraw ובנה לי שורת חיפוש עם embeddings מקומיים ב-Mac\". הוא \"הבין איך\", אבל הקוד היה \"הכי מטורף שכתבתי בחיים\": Python שמייצר תבנית JavaScript בתוך קריאת bash. זה עובד אך איטי, ולכן לא הדגים."],"points":[],"kind":"idea"},{"title":"סיכום והזמנה","body":["סטיב אומר שכל ההדגמות \"רחבות ובלי נקודה\", אבל לקוחות וצוותים לוקחים את אותם רעיונות, מצמצמים אותם, מעלים איכות ומתאימים למשתמשים שלהם. הוא מזמין לנסות: tldraw.dev ל-SDK ו-tldraw.com ללוח לבן חינמי. יש לו זמן לשאלות, והמנחה אומר שיש זמן לשאלה או שתיים. לא נשאלה אף שאלה, וסטיב אומר שיהיה זמין עוד כמה שעות."],"points":[],"kind":"idea"},{"title":"מה נשאר מהסשן","body":[],"points":["הקנבס מתאים ל-AI כי הוא נותן קלט חזותי (ציור והערות) וגם מקום לשיתוף פעולה.","סוכן שמגיב באותן צורות שמשתמש יוצר (ולא בתמונה) מאפשר עריכה משותפת.","בהדגמות חיות היו כשלים (סידור הכפתורים, משחק האיקס־עיגול), והדובר לא הסתיר זאת.","הניסויים רחבים בכוונה, ולקוחות מצמצמים אותם למוצר ממוקד."],"kind":"idea"}],"diagram":{"title":"האבולוציה של ניסויי AI על הקנבס","type":"timeline","nodes":[{"id":"mr","label":"Make Real (2023)","note":"ציור ופרומפט הופכים לאפליקציה, עריכה בהערות"},{"id":"pc","label":"מחשב tldraw","note":"גרפים מכוונים של פרומפטים"},{"id":"sb","label":"סוכן בסרגל הצד (2025)","note":"לולאת סוכן אחת על הקנבס"},{"id":"fa","label":"Fairies","note":"כמה סוכנים על הקנבס, כצוות"},{"id":"dk","label":"אפליקציית desktop","note":"גישה ישירה ל-API של העורך (code mode)"}],"edges":[{"from":"mr","to":"pc","label":"מעבר מתמונה לגרף"},{"from":"pc","to":"sb","label":"סוכן שפועל על הקנבס"},{"from":"sb","to":"fa","label":"יוצא מהסרגל"},{"from":"fa","to":"dk","label":"מכל סוכן, לא רק מבפנים"}]},"terms":[{"term":"קנבס","en":"Canvas","definition":"משטח עבודה אינסופי עם צורות, כמו לוח לבן, שמוצג כאן כאפליקציית React רגילה."},{"term":"Annotation","en":"Annotation","definition":"סימון ידני על הקנבס שנשלח למודל כחלק מהפרומפט."},{"term":"Harness","en":"Harness","definition":"המעטפת והלולאה שמריצה את סוכן ה-AI מול הקנבס."},{"term":"Fairies","en":"Fairies","definition":"סוכנים שחיים על הקנבס, כל אחד מופע של אותו harness, ויכולים לעבוד כצוות."},{"term":"Code mode","en":"Code mode","definition":"גישה שבה נותנים לסוכן להריץ קוד מול API במקום לקרוא לכלי MCP אחד אחד."}],"gaps":["ההרצאה נגמרת אחרי שהמנחה מזמין שאלות; לא נשאלה אף שאלה ולכן אין חלק Q&A.","הכתוביות מעוותות חלקית. \"Gemini 3 flash preview\", \"Stitch\", שמות הקבוצה והגביע של המשחק המומצא כפי שנשמעו.","תיאורי ההדגמות הם לפי דברי הדובר. לא נצפה בסרטון."],"source_refs":["https://www.youtube.com/watch?v=7Sy2gSoxu7o","https://github.com/AINativeDev/aidevcon-2026-ldn"]}]);
